/* Pediatri Nöbet Dengeleyici v2 — arayüz. Tüm hesaplar js/engine.js, js/auditor.js, js/solver.js içindedir. */
(function(){
  "use strict";
  const C=window.NobetCore,E=window.NobetEngine,A=window.NobetAuditor,IA=window.NobetActual,X=window.NobetExport,ST=window.NobetStorage,XP=window.NobetXlsx;
  const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
  const esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  /* tarih metni HTML'e daima kaçışlı basılır (geçersiz/bozuk tarih metni eski veriden ya da düzeltmeden gelebilir) */
  const fd=d=>esc(C.fmtDate(d));
  const fmt=v=>C.fmtNum(v);
  /* sürüm 3: KALICI kayıt yok. Çalışma yalnız bu sekmenin oturum belleğinde (sekme kapanınca silinir).
     exportedClean: son değişiklikten sonra Excel indirildi mi (değilse sekme kapanırken tarayıcı uyarır). oldData: eski sürümün bu tarayıcıda bıraktığı kalıcı kayıt. */
  let dirty=false,exportedClean=true,oldData=null;
  let db=null,step=1,tab="roster",showPreview=false,showRecords=false,staffFilter="",busy=false,rescue=null;
  const M=()=>db.months[db.activeMonth];

  /* ---------------- kayıt ---------------- */
  let saveTimer=null;
  function save(action,detail,o){if(action)E.log(M(),action,detail||"");dirty=true;if(!(o&&o.keepClean))exportedClean=false;$("#saveState").textContent="Kaydediliyor…";clearTimeout(saveTimer);saveTimer=setTimeout(flushSave,120);}
  function flushSave(){renderExportReminder();if(!dirty)return;const r=ST.saveDb(db);if(r.ok){dirty=false;$("#saveState").textContent="Bu sekmede geçici · sekme kapanınca silinir";}else{$("#saveState").textContent="Yalnız bu sayfada — yenilemeyin";notify(r.error,true,15000);}}
  /* telefonda çıkış uyarısı güvenilir değil (FABLE T13-7): Excel indirilene kadar sayfa içinde kalıcı şerit */
  function renderExportReminder(){let b=$("#exportReminder");const show=hasWork()&&!exportedClean;if(!show){if(b)b.remove();return;}if(!b){b=document.createElement("div");b.id="exportReminder";b.className="banner warn";$(".workspace").prepend(b);}b.innerHTML="<b>Excel henüz indirilmedi.</b> Bu sekme kapanınca çalışma silinir (telefonda tarayıcı ayrıca uyarmayabilir). Ara verecekseniz Veri ▾ → “Çalışmayı dosyaya kaydet”.";}
  function renderRescue(){let b=$("#rescueBanner");if(!rescue){if(b)b.remove();return;}if(!b){b=document.createElement("div");b.id="rescueBanner";b.className="banner bad";$(".workspace").prepend(b);}b.innerHTML='<b>Önceki çalışma açılamadı.</b> Ham hâli kaybolmasın diye dosya olarak indirebilirsiniz (personel adları içerir; “Kaydedilmiş çalışmadan devam et” ile yeniden denenebilir). <button class="soft" type="button" data-action="rescue-download">Ham veriyi indir</button> <button class="ghost" type="button" data-action="rescue-dismiss">Kapat</button>';}
  function renderQuarantine(){let b=$("#quarantineBanner");const m=db&&db.months[db.activeMonth];const q=(m&&Array.isArray(m.quarantine))?m.quarantine:[];if(!q.length){if(b)b.remove();return;}if(!b){b=document.createElement("div");b.id="quarantineBanner";b.className="banner warn";$(".workspace").prepend(b);}
    const show=x=>{const k=x.kayit||{};if(x.tur==="izin"||x.tur==="tercih")return`${x.tur}: ${typeof k.pid==="string"?E.personName(db,k.pid):"(kişi yok)"} ${k.start||"(başlangıç yok)"} – ${k.end||"(bitiş yok)"}${k.kind||k.mode?" ("+(k.kind||k.mode)+")":""}`;return`${x.tur}: ${String(JSON.stringify(k)).slice(0,80)}`;};
    b.innerHTML=`<b>Okunamayan ${q.length} kayıt ayrıldı</b> (çalışmanın geri kalanı korundu). Gerekiyorsa doğru tarihle yeniden girin: ${q.slice(0,6).map(x=>esc(show(x))).join(" · ")}${q.length>6?" …":""} <button class="ghost" type="button" data-action="quarantine-clear">Listeyi kapat</button>`;}
  /* FABLE tur13d T13d-1: etkin ayı onarımda boşaltılan dosya da açılır — çalışma (fiilî kayıt ya da çizelge) içeren en son ay, yoksa en son ay;
     onarım bildirimi yalnız açılış başarılıysa */
  function pickMonth(d){if(d.activeMonth)return d.activeMonth;const ks=Object.keys(d.months||{}).filter(k=>E.MONTH_RE.test(k)).sort();const work=ks.filter(k=>{const x=d.months[k];return x&&((x.actual||[]).length||x.result);});return work.pop()||ks.pop()||todayMonth();}
  function adopt(cand){E.validateDb(cand);const notes=E.repairDb(cand);cand.activeMonth=pickMonth(cand);const old=db;db=cand;try{E.ensureMonth(db,db.activeMonth);E.checkStale(db);render();}catch(e){db=old;try{render();}catch(e2){}throw new Error("dosyanın yapısı bozuk ("+(e&&e.message||e)+")");}
    if(notes.length)setTimeout(()=>notify("Dosyadaki bazı kayıtlar okunamadı ve ayrıldı: "+notes.join("; ")+". Geri kalanı açıldı; ayrılan kayıtlar üstteki şeritte.",true,15000),600);}
  function hasWork(){return Object.values(db.months||{}).some(x=>(x.actual||[]).length||x.result||(x.leaves||[]).length);}
  function notify(msg,error=false,ms=6000){const n=$("#notice");n.innerHTML=esc(msg);n.className=`notice${error?" error":""}`;clearTimeout(n._t);n._t=setTimeout(()=>n.classList.add("hidden"),ms);}
  function download(bytes,name,type){const blob=bytes instanceof Blob?bytes:new Blob([bytes],{type:type||"application/octet-stream"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove();},4000);}
  const FMS_RULE_LABEL={halfday:"Arefe nöbeti (hafta içi)",daytime:"Gündüz mesaisi (Cts/Paz/tatil)"};
  function todayMonth(){const d=new Date();return`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;}

  /* ---------------- diyalog ---------------- */
  function dialog(title,html,{ok="Tamam",cancel="Vazgeç",wide=false}={}){return new Promise(res=>{const d=$("#dlg");$("#dlgTitle").textContent=title;$("#dlgBody").innerHTML=html;$("#dlgOk").textContent=ok;$("#dlgCancel").textContent=cancel;$("#dlgCancel").hidden=!cancel;d.classList.toggle("wide",wide);d.onclose=()=>{const v=d.returnValue==="ok";const data={};$$("#dlgBody [name]").forEach(el=>{if(el.type==="radio"){if(el.checked)data[el.name]=el.value;}else data[el.name]=el.type==="checkbox"?el.checked:el.value;});res(v?data:null);};d.returnValue="";d.showModal();const f=$("#dlgBody [autofocus]")||$("#dlgBody input,#dlgBody select,#dlgBody textarea");f&&f.focus();});}

  /* ---------------- başlatma ---------------- */
  function init(){
    $("#appVersion").textContent=C.VERSION;
    const r=ST.loadDb();
    /* yapısı bozuksa reddedilir ama ham hâli kurtarma için saklanır; kayıt kusurları ayrılır, çalışma korunur (FABLE tur13c T13c-1) */
    let ok=null,repairNotes=[];const asRescue=d=>JSON.stringify({format:ST.BACKUP_FORMAT,version:4,createdAt:new Date().toISOString(),note:"Açılamayan oturum (kurtarma kopyası)",db:d,files:{}});
    if(r.db){try{if(E.validateDb(r.db)){repairNotes=E.repairDb(r.db);ok=r.db;}}catch(e){rescue={raw:asRescue(r.db),why:e.message};setTimeout(()=>notify("Oturumdaki çalışma okunamadı ("+e.message+"); yeni oturum başlatıldı. Üstteki şeritten ham veriyi indirebilirsiniz.",true,15000),300);}}
    db=ok||E.newDb();
    if(r.error)setTimeout(()=>notify(r.error,true,12000),300);
    db.activeMonth=pickMonth(db);
    /* açılış da “adopt” gibi korumalı: çizim hata verirse yeni oturuma düşülür (FABLE T13b-2) */
    try{E.ensureMonth(db,db.activeMonth);E.checkStale(db);render();}catch(e){rescue={raw:asRescue(db),why:String(e&&e.message||e)};repairNotes=[];db=E.newDb();db.activeMonth=todayMonth();E.ensureMonth(db,db.activeMonth);setTimeout(()=>notify("Oturumdaki çalışma açılamadı ("+(e&&e.message||e)+"); yeni oturum başlatıldı. Üstteki şeritten ham veriyi indirebilirsiniz.",true,15000),300);}
    bind();render();
    if(repairNotes.length){save("ONARIM",repairNotes.join("; "),{keepClean:true});setTimeout(()=>notify("Oturumdaki bazı kayıtlar okunamadı ve ayrıldı: "+repairNotes.join("; ")+". Çalışmanın geri kalanı korundu; ayrılan kayıtlar üstteki şeritte.",true,15000),400);}
    /* eski sürümün (2.x) kalıcı kaydı: yalnız bulunur; kullanıcı oturuma alır, indirir ya da siler */
    ST.findOldData().then(o=>{oldData=o&&o.found?o:null;renderOldData();}).catch(()=>{});
    const u=ST.sessionUsage();if(u.ratio>0.7)setTimeout(()=>notify(`Oturum belleği yaklaşık %${Math.round(u.ratio*100)} dolu. “Çalışmayı dosyaya kaydet” ile güvenceye alın.`,true,15000),800);
  }
  function openMonth(m){if(!/^\d{4}-\d{2}$/.test(m))return;db.activeMonth=m;E.ensureMonth(db,m);E.checkStale(db);save("AY_ACILDI",m,{keepClean:true});render();const pm=db.months[C.prevMonth(m)];notify(pm&&(pm.result||pm.importedFrom)?`${C.monthLabel(m)} açıldı. Bu oturumdaki ${C.monthLabel(C.prevMonth(m))} bilgileri (son nöbetler, ay sonunu aşan izinler, açık devirler) getirildi.`:`${C.monthLabel(m)} açıldı. Geçen ayın program çıktısı Excel'i varsa Adım 1 → ② bölümünden yükleyin.`);}

  /* ---------------- genel çizim ---------------- */
  function render(){
    $("#monthPick").value=db.activeMonth;
    renderStep1();renderStep2();renderStep3();renderStep4();renderDots();renderStale();renderExportReminder();renderRescue();renderQuarantine();
    $("#sideNote").innerHTML=`<b>${esc(C.monthLabel(db.activeMonth))}</b><br>Çalışmanız yalnız <b>bu sekmede</b> geçici tutulur; sekmeyi kapatınca silinir. Bitince <b>Excel'i indirin</b>: gelecek ay o dosya “Geçen ayın program çıktısı” olarak yüklenir.`;
  }
  function showStep(n){step=+n;$$(".step").forEach(b=>b.classList.toggle("active",+b.dataset.step===step));$$(".step-panel").forEach(p=>p.classList.toggle("active",+p.dataset.panel===step));window.scrollTo({top:0,behavior:"smooth"});render();}
  function renderDots(){
    const m=M();const ps=E.priorStatus(db,m);
    const d1=!m.actualSource?"bad":!m.actualSource.confirmed||!ps.complete?"warn":"good";
    const sug=E.aliasSuggestions(db,m.month).filter(s=>s.blocking).length;const staff=E.staffSummary(db,m);
    const d2=!m.actual.length?"":sug||staff.some(s=>!s.excluded&&s.earnedTarget>0&&!s.allowed.length)?"warn":"good";
    const pre=preflightNow();const d3=!m.settings.rulesConfirmed||pre.some(x=>x.level==="error"&&/RULES|CAP|MIN|HOLIDAY|FMS_UNVERIFIED/.test(x.code))?"warn":"good";
    const r=m.result;const d4=!r?"":r.stale?"bad":r.status==="valid_complete"?"good":r.status==="valid_incomplete"?"warn":"bad";
    [d1,d2,d3,d4].forEach((d,i)=>{$(`#dot${i+1}`).className=`dot ${d}`;});
  }
  /* TALİMATNAME: programın kendi kodundan üretilen parametre belgesi + bu ayın güncel değerleri */
  async function showTalimat(){const T=window.NobetTalimat,V=window.NobetTalimatVeri;if(!T||!V)return notify("Talimatname dosyaları (js/talimatname*.js) bulunamadı.",true);
    const m=M();const stale=V.version!==C.VERSION;
    const head=`<div class="callout${stale?" warn":""}">${stale?"<b>Dikkat:</b> talimatname verisi bu sürüme ait değil. ":""}Paketteki PDF: <a href="TALIMATNAME.pdf" target="_blank" rel="noopener">TALIMATNAME.pdf</a> · <button class="soft" type="button" data-action="talimat-print">Yazdır / PDF olarak kaydet</button></div>`;
    await dialog("Talimatname",`<style>${T.CSS}</style>${head}${T.render(V,{db,month:m.month,monthLabel:C.monthLabel(m.month)})}`,{cancel:"",wide:true});}
  function renderOldData(){let b=$("#oldDataBanner");const o=oldData;if(!o){if(b)b.remove();return;}if(!b){b=document.createElement("div");b.id="oldDataBanner";b.className="banner warn";$(".workspace").prepend(b);}
    b.innerHTML=`<b>Bu tarayıcıda programın eski sürümünden kalmış KALICI kayıt var.</b> Sürüm 3 kalıcı kayıt tutmaz; eski kayıt kendiliğinden silinmez. ${o.raw||o.rawV3?'Eski çalışmayı bu oturuma alabilir ya da dosya olarak indirebilirsiniz. ':''}<span class="nowrap">${o.raw||o.rawV3?'<button class="soft" type="button" data-action="old-import">Bu oturuma al</button> <button class="soft" type="button" data-action="old-download">Dosya olarak indir</button> ':''}<button class="soft danger-text" type="button" data-action="old-delete">Bu bilgisayardan sil</button> <button class="ghost" type="button" data-action="old-dismiss">Şimdilik dokunma</button></span>`;}
  function renderStale(){renderOldData();const m=M();const b=$("#staleBanner");if(m.stale||(m.result&&m.result.stale)){b.classList.remove("hidden");b.innerHTML=`<b>Yeniden denetim gerekli.</b> ${esc(m.stale?.reason||"Girdi verisi değişti.")} <button class="soft" type="button" data-action="run">Yeniden hesapla</button>`;}else b.classList.add("hidden");}
  function preflightNow(){const m=M();const b=E.buildProblem(db,m);return E.preflight(db,m,b.staff,b.bnd);}
  function pill(el,cls,text){el.className=`pill ${cls}`;el.textContent=text;}
  function issueList(list,{max=40,collapsedInfo=true}={}){
    if(!list||!list.length)return"";
    const lv={error:[],warning:[],info:[]};list.forEach(i=>(lv[i.level]||lv.info).push(i));
    const block=(arr,cls,label)=>arr.length?`<div class="issues ${cls}">${arr.slice(0,max).map(i=>`<div class="issue ${cls}"><strong>${label}</strong><span>${esc(i.message)}</span></div>`).join("")}${arr.length>max?`<div class="muted">… ve ${arr.length-max} kayıt daha</div>`:""}</div>`:"";
    return block(lv.error,"error","HATA")+block(lv.warning,"warning","UYARI")+(lv.info.length?(collapsedInfo?`<details class="info-details"><summary>${lv.info.length} bilgi notu</summary>${block(lv.info,"info","BİLGİ")}</details>`:block(lv.info,"info","BİLGİ")):"");
  }

  /* ---------------- ADIM 1 ---------------- */
  function renderStep1(){
    const m=M();const src=m.actualSource;const st=$("#actualStatus");
    if(!src){pill(st,"neutral","Yüklenmedi");$("#actualReport").innerHTML=`<div class="split-actions"><button class="soft" type="button" data-action="add-actual">Elle fiilî kayıt ekle</button></div>${m.actual.length?recordsTable(m):""}`;}
    else{
      pill(st,src.confirmed?"good":"warn",src.confirmed?"Onaylandı":"Onay bekliyor");
      const s=src.stats||{};const low=m.actual.filter(r=>r.status!=="ignored"&&(r.confidence==="düşük"||r.confidence==="orta")&&!r.reviewed);
      const sheets=(src.analysis&&src.analysis.sheets)||[];
      $("#actualReport").innerHTML=`
        <div class="facts">
          <span class="chip">Dosya: <b>${esc(src.fileName)}</b></span>
          ${sheets.length>1?`<label class="chip">Sayfa: <select data-action="change-sheet">${sheets.map(x=>`<option ${x.name===src.sheetName?"selected":""} value="${esc(x.name)}">${esc(x.name)}${x.score>0?"":" (tablo yok)"}</option>`).join("")}</select></label>`:`<span class="chip">Sayfa: <b>${esc(src.sheetName||"—")}</b></span>`}
          <span class="chip ${s.daysFound===s.days?"ok":"bad"}">${s.daysFound??"?"}/${s.days??"?"} gün</span>
          <span class="chip ${s.unitsFound===5?"ok":"warn"}">${s.unitsFound??"?"}/5 bölüm</span>
          <span class="chip">${m.actual.filter(r=>r.status!=="ignored").length} kayıt · ${E.staffSummary(db,m).filter(x=>x.rows.length).length} kişi</span>
          <span class="chip ${low.length?"warn":"ok"}">${low.length} kontrol bekleyen hücre</span>
          ${m.actualOutside.length?`<span class="chip">${m.actualOutside.length} ay dışı kayıt (hakedişe katılmadı)</span>`:""}
          <span class="chip mono" title="Dosya parmak izi (SHA-256)">SHA-256 ${esc((src.fileHash||"").slice(0,12))}…</span>
        </div>
        ${issueList((src.issues||[]).filter(i=>i.code!=="JOINED_LINE"&&i.code!=="SINGLE_WORD"))}
        ${low.length?`<div class="review"><h3>Kontrol bekleyen hücreler</h3><p class="muted">Program emin olamadığı satırları işaretledi. Doğruysa “Doğru”, isim yanlışsa “Düzelt”, nöbet değilse “Yok say”.</p><table><thead><tr><th>Tarih</th><th>Bölüm</th><th>Hücre</th><th>Okunan isim</th><th>Neden</th><th></th></tr></thead><tbody>${low.map(r=>`<tr><td>${fd(r.date)}</td><td>${esc(r.unit)}</td><td class="cell-text">${esc(r.source?.cellText||"")}<br><small class="muted">${esc(r.source?.sheet||"")}!${esc(r.source?.cell||"")}</small></td><td><b>${esc(r.rawName)}</b>${r.shift?` <small>(${r.shift.start}-${r.shift.end})</small>`:""}</td><td><small>${esc((r.flags||[]).map(f=>({"joined-line":"iki satıra bölünmüş isim birleştirildi","single-word":"tek kelimelik isim","continuation-row":"tarihsiz devam satırı","note-line":"not satırı bağlandı"})[f]||f).join(", "))}</small></td><td class="nowrap"><button class="mini" data-action="rec-ok" data-id="${esc(r.id)}">Doğru</button> <button class="mini" data-action="rec-edit" data-id="${esc(r.id)}">Düzelt</button> <button class="mini danger" data-action="rec-ignore" data-id="${esc(r.id)}">Yok say</button></td></tr>`).join("")}</tbody></table></div>`:""}
        <div class="split-actions">
          ${src.confirmed?`<button class="soft" type="button" data-action="unconfirm-import">Onayı geri al</button>`:`<button class="primary" type="button" data-action="confirm-import">İçe aktarmayı onayla</button>`}
          <button class="soft" type="button" data-action="toggle-preview">${showPreview?"Orijinal önizlemeyi gizle":"Orijinal tabloyu göster"}</button>
          <button class="soft" type="button" data-action="toggle-records">${showRecords?"Kayıt listesini gizle":"Okunan kayıtları listele / düzelt"}</button>
          <button class="soft" type="button" data-action="add-actual">Elle fiilî kayıt ekle</button>
          <button class="ghost" type="button" data-action="download-original">Orijinal dosyayı indir</button>
        </div>
        ${showPreview?gridPreview(m):""}
        ${showRecords?recordsTable(m):""}
        ${(m.sourceHistory||[]).length?`<details><summary>Kaynak dosyaların önceki sürümleri (${m.sourceHistory.length})</summary><table><thead><tr><th>Tür</th><th>Dosya</th><th>Yüklendi</th><th>Yerine yenisi</th><th>SHA-256</th><th></th></tr></thead><tbody>${m.sourceHistory.map(h=>`<tr><td>${esc(h.role)}</td><td>${esc(h.fileName)}</td><td><small>${new Date(h.importedAt).toLocaleString("tr-TR")}</small></td><td><small>${new Date(h.replacedAt).toLocaleString("tr-TR")}</small></td><td class="mono">${esc(String(h.fileHash).slice(0,12))}…</td><td><button class="mini" data-action="download-version" data-hash="${esc(h.fileHash)}">indir</button></td></tr>`).join("")}</tbody></table></details>`:""}`;
    }
    renderPrior();
  }
  function gridPreview(m){
    const g=m.actualSource?.grid;if(!g)return'<p class="muted">Önizleme yok (elle girilmiş veri).</p>';
    const byCell=new Map();m.actual.forEach(r=>{const k=r.source?.cell;if(!k)return;(byCell.get(k)||byCell.set(k,[]).get(k)).push(r);});
    const rows=g.rows.map((row,ri)=>`<tr>${row.map((c,ci)=>{if(!c)return"";const recs=byCell.get(c.ref)||[];const cls=ri+g.firstRow===g.headerRow?"hdr":recs.some(r=>r.confidence!=="yüksek"&&!r.reviewed)?"low":recs.length?"ok":"";const tip=recs.map(r=>`${r.rawName} → ${r.unit}${r.shift?" "+r.shift.start+"-"+r.shift.end:""}`).join("\n");return`<td class="${cls}" ${c.rowspan>1?`rowspan="${c.rowspan}"`:""} ${c.colspan>1?`colspan="${c.colspan}"`:""} title="${esc(c.ref+(tip?"\n"+tip:""))}">${esc(c.text).replace(/\n/g,"<br>")}</td>`;}).join("")}</tr>`).join("");
    return`<div class="preview-wrap"><p class="muted">Orijinal sayfa '${esc(m.actualSource.sheetName)}' — yeşil: okunan hücre, sarı: kontrol bekleyen. Üzerine gelince okunan isimler görünür.</p><table class="grid-preview">${rows}</table></div>`;
  }
  function recordsTable(m){
    const LM=E.recordListModel(db,m);const rows=LM.rows,ign=LM.ignored,mis=LM.misplaced;
    const dtx=d=>d?(C.isYmd(d)?fd(d):esc(String(d))):"BOŞ";
    return`<div class="records"><h3>Fiilî kayıtlar (${rows.length+mis.length})${mis.length?` <span class="pill bad">${mis.length} kaydın tarihi ay dışında/geçersiz</span>`:""}</h3><table><thead><tr><th>Tarih</th><th>Personel (kaynak yazımı)</th><th>Bölüm</th><th>Vardiya/not</th><th>FMS</th><th>Eşdeğer</th><th>Kaynak</th><th></th></tr></thead><tbody>${mis.map(r=>`<tr class="row-bad" data-misplaced="1"><td><b class="bad-text">${dtx(r.date)}</b></td><td><b>${esc(r.rawName||"(adsız)")}</b></td><td>${esc(r.unit||"")}</td><td colspan="4"><small class="bad-text">AY DIŞI / TARİH GEÇERSİZ — hakedişe katılmıyor. Tarihi ${esc(C.monthLabel(m.month))} içine düzeltin ya da gerekçesiyle “Yok say”.</small></td><td class="nowrap"><button class="mini" data-action="rec-edit" data-id="${esc(r.id)}">Düzelt</button> <button class="mini danger" data-action="rec-ignore" data-id="${esc(r.id)}">Yok say</button></td></tr>`).join("")}${rows.map(r=>`<tr class="${r.problems.length?"row-bad":""}"><td>${fd(r.date)} <small>${C.dayShort(r.date)}</small></td><td><b>${esc(E.personName(db,r.pid))}</b>${C.fold(r.rawName)!==C.fold(E.personName(db,r.pid))?`<br><small class="muted">kaynakta: ${esc(r.rawName)}</small>`:""}</td><td>${esc(r.unit)}</td><td><small>${r.shift?`${r.shift.start}-${r.shift.end} `:""}${esc((r.notes||[]).join("; "))}</small></td><td>${r.fms==null?'<span class="bad-text">eksik</span>':fmt(r.fms)}<br><small class="muted">${esc(r.fmsSource||r.problems.join("; "))}</small></td><td>${r.eq==null?"—":fmt(r.eq)}</td><td><small>${r.manual?"elle":esc((r.source?.sheet||"")+"!"+(r.source?.cell||""))}</small></td><td class="nowrap"><button class="mini" data-action="rec-edit" data-id="${esc(r.id)}">Düzelt</button> <button class="mini danger" data-action="rec-ignore" data-id="${esc(r.id)}">Yok say</button></td></tr>`).join("")}${ign.map(r=>`<tr class="row-ignored"><td>${dtx(r.date)}</td><td>${esc(r.rawName)}</td><td>${esc(r.unit)}</td><td colspan="4"><small>hakediş dışı${r.ignoreReason?` — gerekçe: ${esc(r.ignoreReason)}`:""}</small></td><td><button class="mini" data-action="rec-restore" data-id="${esc(r.id)}">Geri al</button></td></tr>`).join("")}</tbody></table>
    ${m.actualOutside.length?`<h3>Ay dışı (referans) kayıtlar</h3><p class="muted">Örn. önceki ayın son günü satırı. Bu ayın hakedişine katılmaz; ay sınırı geçen ayın son 3 günündeki RESMÎ nöbetlere göre (Adım 1 → ②) kontrol edilir.</p><div class="facts">${m.actualOutside.map(r=>`<span class="chip">${fd(r.date)} · ${esc(r.unit)} · ${esc(r.rawName)}</span>`).join("")}</div>`:""}</div>`;
  }
  /* ② Geçen ayın son 3 günündeki resmî nöbetler (sürüm 3: PROBEL listesi yüklenmez) — iki yol: (1) geçen ayın program çıktısı, (2) elle giriş */
  function renderPrior(){
    const m=M();const ps=E.priorStatus(db,m);const pmo=C.prevMonth(m.month);const last3=C.monthDates(pmo).slice(-3);
    const dc=E.priorDayCounts(db,m);const thin=dc.filter(x=>x.thin);const doubtful=ps.complete&&m.priorListsComplete&&(dc.every(x=>x.n===0)||thin.length>0);
    pill($("#priorStatus"),doubtful?"warn":ps.complete?"good":ps.any?"warn":"bad",doubtful?"Onaylandı — eksik görünüyor":ps.complete?(ps.manualFill?E.PRIOR_MANUAL_LABEL:"Tam"):ps.any?"Onay bekliyor":"Eksik");
    const staff=E.staffSummary(db,m);const PM=db.months[pmo];const imp=PM&&PM.importedFrom;
    const cats=["Servis","Acil"].filter(c=>m.priorOfficial[c]);const legacy=cats.filter(c=>E.LEGACY_ORIGINS.includes(m.priorOfficial[c].origin));
    const srcName=o=>o==="app-plan"?"program çizelgesi":o==="upload"?"eski PROBEL listesi":"program çizelgesi/PROBEL";
    const known=new Map(last3.map(d=>[d,[]]));
    for(const c of cats)(m.priorOfficial[c].persons||[]).forEach(p=>(p.duties||[]).filter(d=>known.has(d.date)).forEach(d=>known.get(d.date).push(p.name+" ("+c+", "+srcName(m.priorOfficial[c].origin)+")")));
    m.priorManual.filter(x=>x.kind==="duty"&&known.has(x.date)).forEach(x=>known.get(x.date).push(E.personName(db,x.pid)+" (elle)"));
    const nKnown=[...known.values()].reduce((a,x)=>a+x.length,0);
    const yol1=`<div class="callout ${imp?"good":""}" id="carryBox"><b>1) Geçen ayın program çıktısından al</b> — geçen ay bu programla indirdiğiniz Excel'i (“PROGRAM VERİSİ” sayfası olan dosya) yükleyin. Son 3 günün nöbetleriyle birlikte isim kararları, vardiya FMS değerleri, ay sonunu aşan izinler ve devirler de gelir.${imp?`<br><b>Yüklendi:</b> ${esc(imp.file)} · ${esc(new Date(imp.at).toLocaleString("tr-TR"))}`:""} <button class="soft" type="button" data-action="carry-file">${imp?"Başka dosya yükle":"Dosya seç"}</button></div>`;
    const yol2=`<div class="callout" id="manualPriorBox"><b>2) Elle gir</b> — geçen ayın son 3 gününde resmî nöbeti olan kişileri tek tek ekleyin (çıktı dosyası yoksa ya da PROBEL'e farklı girildiyse).
      <div class="editor-grid"><label>Personel<input list="personList" id="pmName" placeholder="Ad Soyad"></label><label>Tarih<select id="pmDate">${last3.map(d=>`<option value="${d}">${fd(d)} ${C.dayName(d)}</option>`).join("")}</select></label><span></span><button class="soft" type="button" data-action="prior-manual-add">Ekle</button></div>
      ${m.priorManual.filter(x=>x.kind==="duty").map(x=>`<div class="mini-row"><b>${esc(E.personName(db,x.pid))}</b><span>${fd(x.date)} resmî nöbet</span><button class="icon-btn" data-action="prior-manual-del" data-pid="${esc(x.pid)}" data-date="${x.date}" title="Sil">×</button></div>`).join("")}</div>`;
    const eski=legacy.length?`<div class="callout warn" id="legacyPriorBox">Önceki sürümde yüklenmiş <b>PROBEL listesi</b> var (${legacy.join(", ")}). Sürüm 3'te PROBEL listesi yüklenmez; bu liste hâlâ ay başı kontrolünde kullanılıyor. ${legacy.map(c=>`<button class="ghost" type="button" data-action="legacy-prior-remove" data-cat="${c}">${c} listesini kaldır</button>`).join(" ")}</div>`:"";
    const ozet=`<div class="callout ${ps.complete?"good":""}" id="priorConfirmBox"><b>Bilinen son 3 gün resmî nöbetleri (${nKnown})</b>${last3.map(d=>`<div class="mini-row"><b>${fd(d)} ${C.dayName(d)}</b><span>${known.get(d).length?esc(known.get(d).join(" · ")):'<span class="muted">—</span>'}${(dc.find(x=>x.date===d)||{}).thin?` <small class="bad-text">— günlük asgariye göre en az ${(dc.find(x=>x.date===d)||{}).min} kişi beklenir</small>`:""}</span></div>`).join("")}
      <label class="check"><input type="checkbox" data-set="priorListsComplete" ${m.priorListsComplete?"checked":""}> <span>Geçen ayın son 3 günündeki resmî nöbetlerin <b>hepsi</b> bu listede (PROBEL'deki kayıtla aynı); başka kimsenin resmî nöbeti yoktu.</span></label>
      <label class="check"><input type="checkbox" data-set="safeBoundary" ${m.settings.safeBoundary?"checked":""}> <span><b>Güvenli mod</b> (önerilir): onay verilmeden ay sonu bilinmeyen kişilere ayın ilk 2 günü nöbet yazılmaz.</span></label></div>`;
    $("#priorExtra").innerHTML=yol1+yol2+eski+ozet+`<datalist id="personList">${staff.map(s=>`<option value="${esc(s.name)}">`).join("")}</datalist>`;
  }

  /* ---------------- ADIM 2 ---------------- */
  function renderStep2(){
    const m=M();const sug=E.aliasSuggestions(db,m.month);
    $("#aliasPanel").innerHTML=sug.length?`<section class="card ${sug.some(s=>s.blocking)?"attention":""}"><div class="card-head"><div><h2>İsim eşleştirme kararları (${sug.length})</h2><p>Benzer yazılmış isimler otomatik birleştirilmez. Kurum sicili/kimlikle teyit edip karar verin; karar sonraki aylarda hatırlanır.${sug.some(s=>s.blocking)?" <b>Kırmızı olanlar çizelgeden önce karar ister.</b>":""}</p></div></div>
      <table><tbody>${sug.map((s,i)=>`<tr class="${s.blocking?"row-bad":""}"><td><b>${esc(s.a)}</b><br><small class="muted">${esc(s.rolesA.join(", "))}</small></td><td>↔</td><td><b>${esc(s.b)}</b><br><small class="muted">${esc(s.rolesB.join(", "))}</small></td><td><small>${esc(s.reason)}</small></td><td class="nowrap"><button class="mini" data-action="alias-same" data-i="${i}">Aynı kişi</button> <button class="mini" data-action="alias-diff" data-i="${i}">Farklı kişiler</button></td></tr>`).join("")}</tbody></table></section>`:"";
    $("#presetPanel").innerHTML="";
    const staff=E.staffSummary(db,m).filter(s=>!staffFilter||C.fold(s.name).includes(C.fold(staffFilter)));
    $("#staffCount").textContent=`${staff.length} kişi`;
    const opt=(v,cur,label)=>`<option value="${v}" ${v===(cur||"")?"selected":""}>${label}</option>`;const nsFlags=E.newStarterFlags(db,m);
    $("#staffTable").innerHTML=`<thead><tr><th>Personel</th><th>Fiilî (bu ay)</th><th>Hakediş<br><small>Servis-eşdeğeri saat</small></th><th>Resmî kategori</th><th>Bu ay hariç</th><th>Fark ödemesi / devir</th></tr></thead><tbody>${staff.map(s=>{const st=s.staff||{};const cats=s.history;
      const catSel=cats.length===1?`<span class="pill neutral">${cats[0]}</span>`:cats.length>1?`<select data-staff="officialCategory" data-pid="${esc(s.pid)}">${opt("",st.officialCategory,"Çözücü seçsin")}${opt("Servis",st.officialCategory,"Servis")}${opt("Acil",st.officialCategory,"Acil")}</select>`:`<select data-staff="authorizedCategory" data-pid="${esc(s.pid)}">${opt("",st.authorizedCategory,"Yetki yok — yazılmaz")}${opt("Servis",st.authorizedCategory,"Servis (yetkili onayı)")}${opt("Acil",st.authorizedCategory,"Acil (yetkili onayı)")}</select>`;
      return`<tr class="${s.excluded?"row-ignored":""}"><td><b>${esc(s.name)}</b>${(db.people[s.pid]?.spellings||[]).length>1?`<br><small class="muted" title="${esc(db.people[s.pid].spellings.join(" · "))}">${db.people[s.pid].spellings.length} yazım</small>`:""}${nsFlags.has(s.pid)?`<br><small class="warn-text">ilk fiilî ${fd(nsFlags.get(s.pid).first)}${nsFlags.get(s.pid).orient?" (oryantasyon)":""} — yeni mi başladı? Başladıysa aşağıdan “Henüz başlamadı” izni girin.</small><br><label class="small"><input type="checkbox" data-staff="startChecked" data-pid="${esc(s.pid)}"> başlangıç kontrol edildi (ay başından beri çalışıyor)</label>`:(s.staff&&s.staff.startChecked?`<br><label class="small"><input type="checkbox" data-staff="startChecked" data-pid="${esc(s.pid)}" checked> başlangıç kontrol edildi</label>`:"")}</td>
        <td>${s.actualDays} gün<br><small>Servis ${fmt(s.servisFms)} · Acil ${fmt(s.acilFms)} FMS</small><br>${cats.map(c=>`<span class="pill ${c==="Servis"?"svc":"acl"}">${c}</span>`).join(" ")||'<span class="muted">nöbet yok</span>'}</td>
        <td><b>${s.earnedComputed==null?'<span class="bad-text">eksik</span>':fmt(s.earnedComputed)}</b>${s.unverified?`<br><small class="bad-text">${s.unverified} kayıt FMS onayı bekliyor</small>`:""}<br><label class="small">Onaylı: <input class="num" type="number" step="0.5" data-staff="earnedOverride" data-pid="${esc(s.pid)}" value="${s.earnedOverride??""}" placeholder="—"></label>${s.earnedOverride!=null&&s.earnedComputed!=null&&s.earnedOverride!==s.earnedComputed?'<br><small class="warn-text">satır hesabıyla çelişiyor</small>':""}</td>
        <td>${catSel}</td>
        <td><input type="checkbox" data-staff="exclude" data-pid="${esc(s.pid)}" ${s.excluded?"checked":""}></td>
        <td><select data-staff="paymentStatus" data-pid="${esc(s.pid)}">${opt("",st.paymentStatus,"Ödeme durumu bilinmiyor")}${opt("unpaid",st.paymentStatus,"Doğrulandı: ödenmedi")}${opt("paid",st.paymentStatus,"Doğrulandı: ödendi")}</select><br><label class="small"><input type="checkbox" data-staff="deferApproved" data-pid="${esc(s.pid)}" ${st.deferApproved?"checked":""}> devir yetkili onaylı</label>${s.openBalance?`<br><label class="small"><input type="checkbox" data-staff="settlePrior" data-pid="${esc(s.pid)}" ${st.settlePrior?"checked":""}> açık devri (${fmt(s.openBalance)}) bu ay kapat</label>`:""}</td>
</tr>`;}).join("")}</tbody>`;
    const people=E.staffSummary(db,m);
    $("#leaveEditor").innerHTML=`<label>Personel<select id="lvPerson">${people.map(s=>`<option value="${esc(s.pid)}">${esc(s.name)}</option>`).join("")}</select></label><label>Tür<select id="lvKind"><optgroup label="İzin — çalışmadığı günler (nöbet yazılmaz)">${E.LEAVE_REASONS.map(r=>`<option value="leave:${esc(r)}">${esc(r)}</option>`).join("")}</optgroup><optgroup label="Nöbet tercihi (izin değil)"><option value="un:avoid">Nöbet istemiyor (tercih)</option><option value="un:prefer">Nöbet istiyor (tercih)</option><option value="un:only">Yalnız bu aralıkta müsait</option></optgroup></select></label><label>Başlangıç<input type="date" id="lvStart"></label><label>Bitiş<input type="date" id="lvEnd"></label><label>Not<input id="lvNote" placeholder="isteğe bağlı"></label><button class="soft" type="button" data-action="leave-add">Ekle</button>`;
    const kindTR={blocked:"kesin müsait değil (izin)",avoid:"nöbet istemiyor (tercih)",prefer:"nöbet istiyor (tercih)",only:"yalnız bu aralıkta müsait"};
    /* eski kayıtlardaki başlama/ayrılış tarihleri de izin listesinde gösterilir (tek yer) */
    const md=C.monthDates(m.month);const legacy=Object.entries(m.staff||{}).flatMap(([pid,st])=>[...(st.startDate&&st.startDate>md[0]?[{pid,kind:"Henüz başlamadı",start:md[0],end:C.addDays(st.startDate,-1),field:"startDate"}]:[]),...(st.endDate&&st.endDate<md[md.length-1]?[{pid,kind:"İşten ayrıldı",start:C.addDays(st.endDate,1),end:md[md.length-1],field:"endDate"}]:[])]);
    $("#leaveList").innerHTML=(m.leaves.length||m.unavailable.length||legacy.length)?`<table><thead><tr><th>Personel</th><th>Tür</th><th>Aralık</th><th>Kaynak / not</th><th></th></tr></thead><tbody>${m.leaves.map(l=>`<tr><td>${esc(E.personName(db,l.pid))}</td><td>${esc(l.kind)}</td><td>${fd(l.start)} – ${fd(l.end)}</td><td><small>${esc([l.source,l.note].filter(Boolean).join(" · "))}</small></td><td><button class="icon-btn" data-action="leave-del" data-id="${esc(l.id)}">×</button></td></tr>`).join("")}${legacy.map(l=>`<tr><td>${esc(E.personName(db,l.pid))}</td><td>${esc(l.kind)} <small class="muted">(eski kayıt)</small></td><td>${fd(l.start)} – ${fd(l.end)}</td><td><small>önceki sürümün başlama/ayrılış alanı</small></td><td><button class="icon-btn" data-action="legacy-del" data-pid="${esc(l.pid)}" data-field="${l.field}">×</button></td></tr>`).join("")}${m.unavailable.map(u=>`<tr><td>${esc(E.personName(db,u.pid))}</td><td>${kindTR[u.mode]}</td><td>${fd(u.start)} – ${fd(u.end)}</td><td><small>${esc(u.note||"")}</small></td><td><button class="icon-btn" data-action="un-del" data-id="${esc(u.id)}">×</button></td></tr>`).join("")}</tbody></table>`:'<p class="muted">Kayıt yok.</p>';
  }

  /* ---------------- ADIM 3 ---------------- */
  function renderStep3(){
    const m=M();const s=m.settings;const g=db.global;const pre=preflightNow().filter(x=>x.level==="error");
    const rows=E.actualRows(db,m);const shiftUse=new Map(),splitUse=new Map();rows.forEach(r=>{if(r.shift&&!(r.shift.start==="08:00"&&r.shift.end==="08:00")){const k=`${r.shift.start}-${r.shift.end}`;const mp=r.split?splitUse:shiftUse;mp.set(k,(mp.get(k)||0)+1);}});
    const oriCount=rows.filter(r=>r.orientation).length;
    /* değeri bu ay GERÇEKTEN gereken vardiya/gün türü: kurala girmeyen, birleşmeyen, aynı gün tam nöbetle çakışmayan saatli kayıt (kullanıcı isteği 14.10.2026) */
    const need=new Set(rows.filter(r=>r.ruleDt&&!r.split&&!r.splitBlocked&&!r.dupOf).map(r=>`${r.shift.start}-${r.shift.end}|${r.ruleDt}`));
    const n=v=>v==null?"":v;
    const sd=s.specialDays||{};const hlist=(s.holidays||[]).map((h,i)=>({...h,i}));const holT=hlist.filter(h=>h.kind!=="yarım gün"),halfT=hlist.filter(h=>h.kind==="yarım gün");
    const dt={weekday:"Hafta içi",friday:"Cuma",saturday:"Cumartesi",sunday:"Pazar",holiday:"Resmî tatil",...(halfT.length?{halfday:"Yarım gün"}:{})};
    const md=C.monthDates(m.month);
    const q=(key,label,val)=>`<div class="question"><b>${label}</b><label class="check inline"><input type="radio" name="sd-${key}" data-special="${key}" value="var" ${val===true?"checked":""}> Evet</label><label class="check inline"><input type="radio" name="sd-${key}" data-special="${key}" value="yok" ${val===false?"checked":""}> Hayır</label>${val==null?'<span class="pill bad">cevap bekliyor</span>':""}</div>`;
    /* yarım gün (arefe) FMS'i girilmez: yetkili kuralı (hafta içi 19, hafta sonu günün normal değeri) — 3.1.0 */
    const halfCell=h=>{const v=C.standardFms(h.date,{fmsTable:g.fmsTable,holidays:[{date:h.date,kind:"yarım gün"}]});const wd=C.weekday(h.date);return`<td><b>${v==null?"—":C.fmtNum(v)}</b> <small class="muted">${wd===0||wd===6?"hafta sonu: günün normal değeri":"kural: hafta içi arefe nöbeti"}</small></td><td><span class="pill good">kural</span></td>`;};
    const dayTable=list=>list.length?`<table><thead><tr><th>Tarih</th><th>Açıklama</th><th>FMS (saat)</th><th>Onay</th><th></th></tr></thead><tbody>${list.map(h=>`<tr><td>${fd(h.date)} ${C.dayName(h.date)}</td><td>${esc(h.label)}</td>${h.kind==="yarım gün"?halfCell(h):`<td><input class="num" type="number" min="0" data-hol="fms" data-i="${h.i}" value="${n(h.fms)}"></td><td><input type="checkbox" data-hol="confirmed" data-i="${h.i}" ${h.confirmed?"checked":""}></td>`}<td><button class="icon-btn" data-action="hol-del" data-i="${h.i}">×</button></td></tr>`).join("")}</tbody></table>`:"";
    /* özel vardiya hücresi: gece → tek başına sayılmaz; gündüz mesaisi Cts/Paz/tatil → kural değeri; bu ay o gün türünde kayıt yoksa → “bu ay gerekmiyor”;
       yalnız gerçekten gereken hücrede kutu çıkar (boşsa “değer girin” vurgusuyla) */
    const shiftCell=(r,k,i)=>C.isNightShift(r)?`<td><small class="muted">tek başına sayılmaz</small></td>`:C.isDaytimeShift(r)&&["saturday","sunday","holiday"].includes(k)?`<td><b>${n(C.tableFms(g.fmsTable,"daytime"))}</b> <small class="muted">kural</small></td>`:!need.has(`${r.start}-${r.end}|${k}`)?`<td><small class="muted">bu ay gerekmiyor</small></td>`:`<td><input class="num" type="number" min="0" step="0.5" data-shift="${k}" data-i="${i}" value="${n(r.fms[k])}">${C.num(r.fms[k])==null?'<br><small class="pill bad">değer girin</small>':""}</td>`;
    const adder=(kind,id,ph,btn)=>`<div class="editor-grid"><label>${kind==="yarım gün"?"Yarım gün":"Tatil günü"}<input type="date" id="${id}Date" min="${md[0]}" max="${md[md.length-1]}"></label><label>Açıklama<input id="${id}Label" placeholder="${ph}"></label><span></span><span></span><button class="soft" type="button" data-action="hol-add" data-kind="${kind}">${btn}</button></div>`;
    const specialCard=`<section class="card" id="specialDaysCard"><div class="card-head"><div><h2>Resmî tatil ve yarım gün (${C.monthLabel(m.month)})</h2><p>Program bu günleri <b>tahmin etmez</b>; her ay sorar (ör. 29 Ekim resmî tatil, 28 Ekim yarım gün). Resmî tatilin FMS değerini kurum kuralına göre girip onaylayın. <b>Yarım gün (arefe)</b> nöbetinin FMS'i yetkili kuralıyla belli: hafta içine denk gelirse <b>19</b> (24 − 5 saat mesai), hafta sonuna denk gelirse o günün normal değeri. İki soru cevaplanmadan çizelge oluşturulmaz.</p></div></div>
      ${q("holiday","1) Bu ay resmî tatil var mı?",sd.holiday)}${sd.holiday===true?dayTable(holT)+adder("tatil","hol","ör. Cumhuriyet Bayramı","Tatil günü ekle"):dayTable(holT)}
      ${q("halfDay","2) Bu ay yarım gün çalışma (ör. bayram arifesi) var mı?",sd.halfDay)}${sd.halfDay===true?dayTable(halfT)+adder("yarım gün","half","ör. Cumhuriyet Bayramı arifesi","Yarım gün ekle"):dayTable(halfT)}</section>`;
    $("#rulesBody").innerHTML=`
      ${pre.length?`<section class="card attention"><h2>Çizelgeden önce tamamlanacaklar (${pre.length})</h2>${issueList(pre,{max:25})}</section>`:`<div class="callout good">Veri ve onay eksiği yok.</div>`}
      ${specialCard}
      <section class="card"><div class="card-head"><div><h2>Günlük kadro sınırları</h2><p>Acil = Acil + Yoğun Bakım + Yenidoğan + Kıdemli (aynı gün farklı kişi sayısı). Asgari değerler klinik yönetimince belirlenmelidir; 0 da girilebilir.</p></div></div>
        <div class="settings-grid"><label>Acil günlük EN FAZLA (kişi)<input type="number" min="0" data-set="emergencyCap" value="${n(s.emergencyCap)}"></label><label>Acil günlük EN AZ<input type="number" min="0" data-set="emergencyMin" value="${n(s.emergencyMin)}" placeholder="girilmedi"></label><label>Servis günlük EN AZ<input type="number" min="0" data-set="serviceMin" value="${n(s.serviceMin)}" placeholder="girilmedi"></label><label>Servis günlük EN FAZLA<input type="number" min="0" data-set="serviceMax" value="${n(s.serviceMax)}" placeholder="sınır yok"></label></div>
        <details ${m.dailyRequirements.length?"open":""}><summary>Belirli günler için farklı sınır (${m.dailyRequirements.length})</summary>
        <div class="editor-grid"><label>Tarih<input type="date" id="drDate" min="${C.monthDates(m.month)[0]}" max="${C.monthDates(m.month).slice(-1)[0]}"></label><label>Servis en az<input type="number" id="drSmin" min="0"></label><label>Servis en fazla<input type="number" id="drSmax" min="0"></label><label>Acil en az<input type="number" id="drEmin" min="0"></label><label>Acil en fazla<input type="number" id="drEmax" min="0"></label><button class="soft" type="button" data-action="dr-add">Ekle</button></div>
        ${m.dailyRequirements.map(d=>`<div class="mini-row"><b>${fd(d.date)}</b><span>Servis ${n(d.serviceMin)||"·"}–${n(d.serviceMax)||"·"} · Acil ${n(d.emergencyMin)||"·"}–${n(d.emergencyMax)||"·"}</span><button class="icon-btn" data-action="dr-del" data-date="${d.date}">×</button></div>`).join("")}</details></section>
      <section class="card"><div class="card-head"><div><h2>Hakediş modu</h2></div></div>
        <label class="check"><input type="radio" name="mode" data-set="mode" value="strict" ${s.mode!=="defer"?"checked":""}> <span><b>Devirsiz (önerilir):</b> herkesin resmî karşılığı fiilî hakedişinden az olamaz.</span></label>
        <label class="check"><input type="radio" name="mode" data-set="mode" value="defer" ${s.mode==="defer"?"checked":""}> <span><b>Onaylı devir:</b> izin/kapasite nedeniyle karşılanamayan fark, ödeme teyidi ve yetkili onayıyla sonraki aya devredilebilir.</span></label>
        <div class="settings-grid"><label>Devirleri onaylayan yetkili<input data-set="approvedBy" value="${esc(s.approvedBy||"")}" placeholder="Ad Soyad / unvan"></label></div>
        ${(m.currentOfficial.Servis||m.currentOfficial.Acil)?`<div class="callout warn" id="legacyCurrentBox">Önceki sürümde yüklenmiş <b>bu ayın PROBEL listesi</b> var (${["Servis","Acil"].filter(c=>m.currentOfficial[c]).join(", ")}). Hâlâ hesaba katılıyor: NSİ günleri engel sayılıyor, işlenmiş nöbetler korunmaya çalışılıyor. Sürüm 3'te bu ayın PROBEL listesi kullanılmaz; kaldırmanız önerilir. <button class="ghost" type="button" data-action="legacy-current-remove">Listeyi kaldır</button></div>`:""}</section>
      <section class="card"><div class="card-head"><div><h2>Özel vardiyaların FMS değerleri</h2><p>Excel'de saat notuyla yazılmış görevler (ör. 09.00–17.00, 17.00–08.00). Değerler kaydedilir; sonraki aylarda tekrar sorulmaz. <b>Tahmin yapılmaz</b>: boş değer o kaydı “veri eksik” bırakır. <b>Yetkili kuralları:</b> tek başına <b>gündüz mesaisi</b> (08.00–16.00 / 09.00–17.00 gibi) Cumartesi, Pazar ve resmî tatilde <b>${n(C.tableFms(g.fmsTable,"daytime"))} FMS</b> (sorulmaz). <b>İki yerde nöbet:</b> aynı kişi Cumartesi ya da Pazar iki farklı Acil ailesi bölümünde saatli görev yaptıysa (ör. Acil 17.00–08.00 + Yenidoğan 09.00–17.00) o gün tek tam nöbet sayılır (kategori Acil, günün standart FMS'i). Tek başına gece görevi, hafta içi iki yer ve Servis + Acil karışık gün olmaz: böyle kayıt uyarı verir, düzeltilene kadar sayılmaz.</p></div></div>
        ${g.specialShiftRules.length?`<table><thead><tr><th>Vardiya</th><th>Bu ay</th>${Object.values(dt).map(x=>`<th>${x}</th>`).join("")}<th></th></tr></thead><tbody>${g.specialShiftRules.map((r,i)=>`<tr><td><b>${esc(r.start)}–${esc(r.end)}</b></td><td>${shiftUse.get(`${r.start}-${r.end}`)||0} kayıt${splitUse.get(`${r.start}-${r.end}`)?`<br><small class="muted">+ ${splitUse.get(`${r.start}-${r.end}`)} iki yerde nöbet parçası (FMS sorulmaz)</small>`:""}</td>${Object.keys(dt).map(k=>shiftCell(r,k,i)).join("")}<td><button class="icon-btn" data-action="shift-del" data-i="${i}">×</button></td></tr>`).join("")}</tbody></table>`:'<p class="muted">Özel vardiya görülmedi.</p>'}
        <p class="muted" id="orientationNote"><b>Oryantasyon nöbeti</b> (${oriCount} kayıt bu ay): her zaman gerçek nöbet gibi sayılır — günün standart FMS'i (kullanıcı kararı).</p></section>
      <section class="card"><div class="card-head"><div><h2>Standart FMS tablosu ve katsayılar (tüm aylar)</h2><p>Kullanıcı tarafından bildirilen kural: Pazartesi–Perşembe 8, Cuma 16, Cumartesi 24, Pazar 16. Yetkili kuralı (14.10.2026): hafta içi arefe nöbeti 19; tek başına gündüz mesaisi (Cumartesi, Pazar, resmî tatil) 8. Servis-eşdeğeri saat = Servis FMS × 1 + Acil ailesi FMS × 1,5.</p></div><label class="check"><input type="checkbox" id="unlockFms"> değiştir</label></div>
        <div class="settings-grid fms-grid">${[1,2,3,4,5,6,0].map(d=>`<label>${C.DAYS_TR[d]}<input type="number" min="0" data-fms="${d}" value="${g.fmsTable[d]}" disabled></label>`).join("")}${Object.entries(FMS_RULE_LABEL).map(([k,l])=>`<label>${l}<input type="number" min="0" data-fms="${k}" value="${n(C.tableFms(g.fmsTable,k))}" disabled></label>`).join("")}<label>Servis katsayısı<input type="number" step="0.5" data-factor="Servis" value="${g.factors.Servis}" disabled></label><label>Acil katsayısı<input type="number" step="0.5" data-factor="Acil" value="${g.factors.Acil}" disabled></label></div></section>
      <label class="confirm check ${s.rulesConfirmed?"good":""}"><input type="checkbox" data-set="rulesConfirmed" ${s.rulesConfirmed?"checked":""}> <span><b>Bu ayın kurallarını yetkili kişiyle kontrol ettim ve onaylıyorum.</b><small>Kadro sınırları, FMS tablosu, tatil ve özel vardiya değerleri. Herhangi bir kural değişirse onay kendiliğinden kalkar.</small></span></label>`;
  }

  /* ---------------- ADIM 4 ---------------- */
  function renderStep4(){
    const m=M();const r=m.result;
    const enable=!!(r&&r.assignments&&r.assignments.length);
    $$('[data-action="export"],[data-action="export-probel"],[data-action="print"]').forEach(b=>b.disabled=!enable);
    $('[data-action="carry"]').disabled=!(r&&["valid_complete","valid_incomplete"].includes(r.status)&&!r.stale);
    if(!r){$("#resultIntro").textContent="Henüz oluşturulmadı. Adım 1–3 tamamlanınca “Çizelgeyi oluştur”a basın.";$("#statusBadge").className="status neutral";$("#statusBadge").textContent="Bekliyor";$("#resultMetrics").innerHTML="";$("#issues").innerHTML="";$("#resultBody").innerHTML="";return;}
    const errs=r.issues.filter(i=>i.level==="error"),warns=r.issues.filter(i=>i.level==="warning");
    const cls=r.stale?"bad":r.status==="valid_complete"?"good":r.status==="valid_incomplete"?"warn":"bad";
    $("#statusBadge").className=`status ${cls}`;$("#statusBadge").textContent=r.stale?"YENİDEN DENETLENMELİ":X.STATUS_TR[r.status]||r.status;
    $("#resultIntro").innerHTML=`${esc(r.statusText)}${r.solver?` · ${esc(r.solver.engine)} · ${r.solver.elapsedMs} ms`:""} · ${new Date(r.generatedAt).toLocaleString("tr-TR")}`;
    const rec=r.reconciliation||[];const over=rec.reduce((z,x)=>z+(x.difference!=null&&x.difference<0?-x.difference:0),0),pend=rec.filter(x=>!x.excluded&&/bekliyor/.test(x.decision)).reduce((z,x)=>z+(x.difference||0),0),exc=rec.filter(x=>x.excluded).reduce((z,x)=>z+(x.earnedTarget||0),0),carry=rec.reduce((z,x)=>z+(x.carry||0),0);
    $("#resultMetrics").innerHTML=[["Resmî görev",r.assignments.length],["Kesin hata",errs.length],["Uyarı",warns.length],["Fazla ödeme (eşd. saat)",`${fmt(over)}${r.overBound?`<br><small class="muted">plan ${fmt(r.overBound.total)} · en az olası ${fmt(r.overBound.lowerBound)}${r.overBound.atBound?" ✓":""}</small>`:""}`],["Mutabakat bekleyen fark",fmt(pend)],["Onaylı devir",fmt(carry)],["Hariçlerin fiilî hakedişi",fmt(exc)]].map(([a,b])=>`<div class="metric"><span>${a}</span><strong>${b}</strong></div>`).join("");
    $("#issues").innerHTML=(r.blockedRun?`<section class="card attention"><h2>Son hesaplama yapılamadı (${esc(new Date(r.blockedRun.at).toLocaleString("tr-TR"))})</h2><p>Aşağıdaki eksikler tamamlanınca yeniden hesaplayın. Görüntülenen çizelge <b>önceki hesaplamadır</b> ve yeniden denetlenmelidir.</p>${issueList(r.blockedRun.issues,{max:20})}</section>`:"")+issueList(r.issues,{max:30})+scenarioBar(m);
    $$(".subtabs [data-tab]").forEach(b=>b.classList.toggle("active",b.dataset.tab===tab));
    $("#resultBody").innerHTML=resultTab(m,r);
  }
  function scenarioBar(m){const list=m.scenarios||[];return`<details class="card"><summary>Senaryolar (${list.length}) — bu sonucu adlandırıp saklayın; eski senaryolar silinmez</summary><div class="editor-grid"><label>Senaryo adı<input id="scName" placeholder="ör. Acil üst sınır 8, Servis en az 1"></label><span></span><span></span><span></span><span></span><button class="soft" type="button" data-action="sc-save">Kaydet</button></div>${list.map((sc,i)=>`<div class="mini-row"><b>${esc(sc.name)}</b><span>${new Date(sc.at).toLocaleString("tr-TR")} · ${esc(X.STATUS_TR[sc.result?.status]||"")} · ${sc.result?.assignments?.length||0} görev</span><button class="mini" data-action="sc-load" data-i="${i}">Ayarları ve sonucu geri yükle</button></div>`).join("")}</details>`;}
  function resultTab(m,r){
    const dates=C.monthDates(m.month);
    if(tab==="roster"){const lim=E.dailyLimits(m);return`<p class="muted">Bir ismi kaldırmak için ×, eklemek için + kullanın; her değişiklik bağımsız denetimden yeniden geçer.</p><table class="roster"><thead><tr><th>Tarih</th><th>Gün</th><th>SERVİS</th><th>ACİL ailesi (Acil/YB/YD/Kıdemli)</th></tr></thead><tbody>${dates.map((d,i)=>{const a=r.assignments.filter(x=>x.date===d);const we=[0,6].includes(C.weekday(d));const cell=cat=>{const list=a.filter(x=>x.category===cat);const L=lim[i][cat];const bad=(L.min!=null&&list.length<L.min)||(L.max!=null&&list.length>L.max);return`<td class="${bad?"cell-bad":""}">${list.map(x=>`<span class="name ${x.source==="elle"?"manual":""}">${esc(x.name)} <button class="x" data-action="as-del" data-id="${esc(x.id)}" title="Kaldır">×</button></span>`).join("")}<button class="plus" data-action="as-add" data-date="${d}" data-cat="${cat}" title="Ekle">+</button><small class="count">${list.length}${L.max!=null?"/"+L.max:""}</small></td>`;};return`<tr class="${we?"we":""}"><td>${fd(d)}</td><td>${C.dayName(d)}</td>${cell("Servis")}${cell("Acil")}</tr>`;}).join("")}</tbody></table>`;}
    if(tab==="people"){const rec=r.reconciliation||[];const sp=rec.some(x=>x.postedFms!=null);return`<table><thead><tr><th>Personel</th><th>Fiilî Servis FMS</th><th>Fiilî Acil FMS</th><th>Kazanılan eşdeğer</th><th>Resmî kategori</th><th>Resmî gün</th><th>Resmî FMS</th><th>Resmî eşdeğer</th>${sp?"<th>PROBEL FMS (eski sürümden yüklenen)</th>":""}<th>Fark</th><th>Önceki açık</th><th>Karar</th><th>Kapanış açık</th></tr></thead><tbody>${rec.map(x=>`<tr class="${x.excluded?"row-ignored":""}"><td><b>${esc(x.name)}</b>${x.excluded?" <small>(hariç)</small>":""}</td><td>${fmt(x.servisFms)}</td><td>${fmt(x.acilFms)}</td><td>${x.earnedTarget==null?'<span class="bad-text">eksik</span>':fmt(x.earnedTarget)}${x.earnedOverride!=null?`<br><small>onaylı (hesap: ${fmt(x.earnedComputed)})</small>`:""}</td><td>${esc(x.plannedCategory)}</td><td>${x.plannedDays}</td><td>${fmt(x.plannedFms)}</td><td>${fmt(x.plannedEq)}</td>${sp?`<td>${x.postedFms==null?"—":fmt(x.postedFms)}</td>`:""}<td class="${x.difference>0?"warn-text":x.difference<0?"muted":""}"><b>${x.difference==null?"—":fmt(x.difference)}</b><br><small>${esc(x.basis)}</small></td><td>${fmt(x.openingOpen)}</td><td><small>${esc(x.decision)}</small></td><td>${fmt(x.closingOpen)}</td></tr>`).join("")}</tbody></table><p class="muted">Fark = kazanılan eşdeğer − resmî karşılık${sp?" (eski sürümden yüklenen PROBEL listesi varsa onun FMS'i esas alınır)":""}. Pozitif fark ödeme teyidi ve yetkili onayı olmadan alacak sayılmaz.</p>`;}
    if(tab==="compare"){const staff=E.staffSummary(db,m);return`<table><thead><tr><th>Personel</th><th>Fiilî görev günleri</th><th>Resmî nöbet günleri</th><th>Aynı gün</th></tr></thead><tbody>${staff.filter(s=>s.rows.length||r.assignments.some(a=>a.pid===s.pid)).map(s=>{const act=s.rows.map(x=>`${x.date.slice(8)}${x.category==="Acil"?"A":"S"}${x.shift?"*":""}`);const off=r.assignments.filter(a=>a.pid===s.pid);const same=off.filter(a=>s.rows.some(x=>x.date===a.date)).length;return`<tr><td><b>${esc(s.name)}</b></td><td class="mono">${act.join(" ")}</td><td class="mono">${off.map(a=>`${a.date.slice(8)}${a.category[0]}`).join(" ")}</td><td>${same}/${off.length}</td></tr>`;}).join("")}</tbody></table><p class="muted">S=Servis, A=Acil ailesi, *=özel saatli görev. Fiilî kayıtlar değiştirilmez; resmî tarihler kurallar gereği farklı olabilir.</p>`;}
    if(tab==="daily"){const lim=E.dailyLimits(m);return`<table><thead><tr><th>Tarih</th><th>Gün</th><th>Servis</th><th>Servis sınırı</th><th>Acil (farklı kişi)</th><th>Acil sınırı</th><th>Fiilî Servis</th><th>Fiilî Acil</th></tr></thead><tbody>${dates.map((d,i)=>{const a=r.assignments.filter(x=>x.date===d);const s=a.filter(x=>x.category==="Servis").length,c=new Set(a.filter(x=>x.category==="Acil").map(x=>x.pid)).size;const L=lim[i];const act=E.actualRows(db,m).filter(x=>x.date===d);return`<tr><td>${fd(d)}</td><td>${C.dayName(d)}</td><td><b>${s}</b></td><td>${L.Servis.min??"—"}–${L.Servis.max??"∞"}</td><td><b>${c}</b></td><td>${L.Acil.min??"—"}–${L.Acil.max??"∞"}</td><td>${new Set(act.filter(x=>x.category==="Servis").map(x=>x.pid)).size}</td><td>${new Set(act.filter(x=>x.category==="Acil").map(x=>x.pid)).size}</td></tr>`;}).join("")}</tbody></table>`;}
    if(tab==="boundary"){const staff=E.staffSummary(db,m);const b=E.boundaryBlocks(db,m,staff);const ps=b.status;return`<div class="callout ${ps.complete?"good":"warn"}">Geçen ayın son 3 günündeki resmî nöbetler: ${ps.complete?(ps.manualFill?esc(E.PRIOR_MANUAL_LABEL):"onaylandı (hepsi burada)"):ps.planBased?"program çıktısından geldi, onay bekliyor":ps.any?"girildi, “hepsi burada” onayı bekliyor":"girilmedi"}. ${ps.complete?"Ay başı sınırı resmî kayda göre kontrol edildi.":"Ay başı sınırı TAM doğrulanmadı (Adım 1 → ②)."}</div><table><thead><tr><th>Personel</th><th>Kapalı gün(ler)</th><th>Tür</th><th>Neden</th></tr></thead><tbody>${[...b.blocks.entries()].map(([pid,arr])=>`<tr><td><b>${esc(E.personName(db,pid))}</b></td><td>${arr.map(x=>fd(x.date)).join(", ")}</td><td>${C.uniq(arr.map(x=>x.kind)).join("/")}</td><td><small>${esc(C.uniq(arr.map(x=>x.reason)).join(" · "))}</small></td></tr>`).join("")||'<tr><td colspan="4" class="muted">Engel yok.</td></tr>'}</tbody></table>`;}
    if(tab==="ledger"){const bal=E.ledgerBalances(m);const staff=E.staffSummary(db,m);return`<h3>Açık devir bakiyeleri</h3><table><thead><tr><th>Alacak</th><th>Personel</th><th>Kaynak ay</th><th>Tutar</th><th>Ödenen/mahsup</th><th>Açık</th><th>Onaylayan</th></tr></thead><tbody>${bal.map(c=>`<tr><td class="mono">${esc(c.claimId)}</td><td>${esc(E.personName(db,c.pid))}</td><td>${esc(c.sourceMonth||"")}</td><td>${fmt(c.units)}</td><td>${fmt(c.settled)}</td><td><b>${fmt(c.open)}</b></td><td>${esc(c.approvedBy)}</td></tr>`).join("")||'<tr><td colspan="7" class="muted">Açık alacak yok.</td></tr>'}</tbody></table>
      <div class="editor-grid"><label>İşlem<select id="lgKind"><option value="payment">Doğrulanmış ödeme / mahsup</option><option value="carry-open">Açılış alacağı (yetkili onaylı)</option></select></label><label>Alacak (ödeme için)<select id="lgClaim"><option value="">—</option>${bal.filter(c=>c.open>0).map(c=>`<option value="${esc(c.claimId)}">${esc(E.personName(db,c.pid))} · ${esc(c.claimId)} · açık ${fmt(c.open)}</option>`).join("")}</select></label><label>Personel (alacak için)<select id="lgPid">${staff.map(s=>`<option value="${esc(s.pid)}">${esc(s.name)}</option>`).join("")}</select></label><label>Eşdeğer saat<input type="number" step="0.5" id="lgUnits"></label><label>Belge / onaylayan<input id="lgRef" placeholder="bordro no / yetkili"></label><button class="soft" type="button" data-action="ledger-add">Deftere ekle</button></div>
      <h3>Defter hareketleri (silinmez)</h3><table><thead><tr><th>Zaman</th><th>İşlem</th><th>Alacak</th><th>Personel</th><th>Saat</th><th>Onay/Belge</th><th>Not</th></tr></thead><tbody>${(m.ledger||[]).map(e=>`<tr><td><small>${new Date(e.at).toLocaleString("tr-TR")}</small></td><td>${esc(e.kind)}</td><td class="mono">${esc(e.claimId||"")}</td><td>${esc(E.personName(db,e.pid||""))}</td><td>${fmt(C.num(e.units))}</td><td>${esc(e.approvedBy||e.reference||"")}</td><td><small>${esc(e.note||"")}</small></td></tr>`).join("")||'<tr><td colspan="7" class="muted">Hareket yok.</td></tr>'}</tbody></table>`;}
    return`<table><thead><tr><th>Zaman</th><th>İşlem</th><th>Ayrıntı</th></tr></thead><tbody>${[...(m.auditLog||[])].reverse().map(x=>`<tr><td><small>${new Date(x.at).toLocaleString("tr-TR")}</small></td><td>${esc(x.action)}</td><td><small>${esc(x.detail)}</small></td></tr>`).join("")}</tbody></table>`;
  }

  /* ---------------- dosya içe aktarma ---------------- */
  async function readBytes(file){return new Uint8Array(await file.arrayBuffer());}
  async function importActualFile(file,sheetName){
    try{
      const bytes=await readBytes(file);const hash=C.sha256Hex(bytes);
      await ST.putFile(hash,{name:file.name,type:file.type||"",addedAt:new Date().toISOString(),role:"fiilî",bytes:bytes.buffer.slice(bytes.byteOffset,bytes.byteOffset+bytes.byteLength)});
      if(!ST.fileInSession(hash))setTimeout(()=>notify("Excel dosyası oturum belleğine sığmadı: sayfayı yenilerseniz biçimli çıktı için dosyayı yeniden yüklemeniz gerekir.",true,15000),400);
      await applyActualBytes(bytes,{name:file.name,hash,size:bytes.length},sheetName);
    }catch(e){console.error(e);notify("Dosya okunamadı: "+e.message,true,12000);}
  }
  async function mappingDialog(bytes,meta,wb){
    const v=await dialog("Sütunları elle eşle",`<p class="muted">Program başlık satırını bulamadı. Excel'de gördüğünüz satır numarası ve sütun harflerini girin; eşleme kaydedilir ve sonraki aylarda aynı biçim için kullanılır.</p><label>Sayfa<select name="sheet">${wb.SheetNames.map(n=>`<option>${esc(n)}</option>`).join("")}</select></label><label>Başlık satırı (ör. 3)<input name="row" type="number" min="1" required></label><label>Tarih sütunu (ör. A)<input name="date" required maxlength="3"></label>${C.UNITS.map(u=>`<label>${u} sütunu (boş = yok)<input name="u_${u}" maxlength="3"></label>`).join("")}`,{ok:"Bu eşlemeyle oku"});
    if(!v)return;const col=s=>{s=String(s||"").trim().toUpperCase();if(!/^[A-Z]{1,3}$/.test(s))return null;return C.parseA1(s+"1").c;};
    const units={};for(const u of C.UNITS){const c=col(v["u_"+u]);if(c!=null)units[u]=c;}
    if(!Object.keys(units).length||col(v.date)==null)return notify("Tarih sütunu ve en az bir bölüm sütunu gerekli.",true);
    const mapping={sheetName:v.sheet,headerRow:(+v.row)-1,dateCol:col(v.date),units};
    db.global.importMapping=mapping;save("SUTUN_ESLEME",JSON.stringify(mapping));
    await applyActualBytes(bytes,meta,v.sheet,mapping);
  }
  async function applyActualBytes(bytes,meta,sheetName,mappingOverride){
    const isZip=bytes[0]===0x50&&bytes[1]===0x4b;const lower=meta.name.toLowerCase();
    const wb=XLSX.read(bytes,{type:"array",cellDates:false});
    let {analysis,result}=IA.parseWorkbook(XLSX,wb,{fileName:meta.name,sheetName,mapping:mappingOverride||undefined,preferMonth:db.activeMonth});
    /* otomatik bulunamazsa: daha önce kaydedilen elle eşleme ile dene */
    if(!result.records.length&&!mappingOverride&&db.global.importMapping){const sn=db.global.importMapping.sheetName&&wb.SheetNames.includes(db.global.importMapping.sheetName)?db.global.importMapping.sheetName:(sheetName||analysis.best||wb.SheetNames[0]);const r2=IA.parseWorkbook(XLSX,wb,{fileName:meta.name,sheetName:sn,mapping:db.global.importMapping});if(r2.result.records.length){result=r2.result;analysis=r2.analysis;notify("Kayıtlı sütun eşlemesi kullanıldı.");}}
    if(!result.records.length&&result.issues.some(i=>i.level==="error")){notify("İçe aktarılamadı: "+result.issues.filter(i=>i.level==="error").map(i=>i.message).join(" · ")+" — sütunları elle eşleyebilirsiniz.",true,15000);await mappingDialog(bytes,meta,wb);return;}
    let month=result.month||db.activeMonth;
    if(month!==db.activeMonth){db.activeMonth=month;E.ensureMonth(db,month);notify(`Dosya ${C.monthLabel(month)} ayına ait; çalışılan ay buna göre değiştirildi.`);}
    const m=E.setActualImport(db,month,result,{...meta,format:isZip&&/\.(xlsx|xlsm)$/.test(lower)?"xlsx":lower.split(".").pop()});
    m.actualSource.analysis=analysis;m.actualSource.grid=result.grid;
    showPreview=true;save("FIILI_ICE_AKTARIM",meta.name);render();
    notify(`${result.records.length} fiilî kayıt okundu (${result.stats.daysFound}/${result.stats.days} gün, ${result.stats.unitsFound}/5 bölüm). Önizlemeyi kontrol edip “İçe aktarmayı onayla”ya basın.`);
  }
  /* ---------------- çözüm ve dışa aktarma ---------------- */
  function run(){if(busy)return;busy=true;const b=$('[data-action="run"]');const old=b.textContent;b.textContent="Hesaplanıyor…";b.disabled=true;
    setTimeout(()=>{try{const r=E.run(db,db.activeMonth);save("COZUM",r.status);tab="roster";showStep(4);notify(r.status==="valid_complete"?"Çizelge geçerli; bağımsız denetimden geçti.":r.status==="valid_incomplete"?"Çizelge kurallara uygun; ancak eksik veri var (uyarılara bakın).":r.statusText,r.status!=="valid_complete"&&r.status!=="valid_incomplete");}catch(e){console.error(e);notify("Hesaplama hatası: "+e.message,true,15000);}finally{busy=false;b.textContent=old;b.disabled=false;}},30);}
  async function exportExcel(){
    const m=M();const r=m.result;if(!r)return;const mode=$("#exportMode").value;
    try{
      let rec=m.actualSource?.fileHash?await ST.getFile(m.actualSource.fileHash):null;
      const bytes=rec?new Uint8Array(rec.bytes):null;
      if(bytes&&bytes[0]===0x50&&bytes[1]===0x4b&&m.actualSource.format==="xlsx"){
        const out=X.buildPreserved(XLSX,bytes,db,m,r,mode);download(out.bytes,X.fileName(m,r,mode==="inplace"?"orijinal_guncel":"orijinal_ve_oneri"),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        save("EXCEL",`${mode}; biçim doğrulaması ${out.verify.ok?"GEÇTİ":"KALDI"}`);exportedClean=true;
        await dialog("Excel hazırlandı",`<p>Dosya indirildi. Biçim koruma denetimi: <b class="${out.verify.ok?"good-text":"bad-text"}">${out.verify.ok?"GEÇTİ":"SORUN VAR"}</b></p><ul class="checklist">${out.verify.checks.map(c=>`<li class="${c.ok?"ok":"bad"}">${c.ok?"✓":"✗"} ${esc(c.name)}${c.detail&&!c.ok?` — ${esc(c.detail)}`:""}</li>`).join("")}</ul><p class="muted">${mode==="clone"?"Orijinal sayfalar hiç değiştirilmedi; resmî öneri “RESMİ ÖNERİ” sayfasında, aynı biçimde.":"Orijinal dosyanın KOPYASINDA tablo hücreleri resmî çizelgeyle değiştirildi; bilgisayarınızdaki orijinal dosya değişmez."} Acil/YB/YD/Kıdemli resmî olarak tek kategori olduğu için ACİL sütununa yazılır.</p>`,{cancel:""});
      }else{
        const out=X.buildFallback(XLSX,db,m,r);download(out,X.fileName(m,r,"bicimsiz"),"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
        notify(bytes?"Kaynak dosya .xlsx olmadığı için biçim korunamadı; düz tablo üretildi (dosyadaki uyarı sayfasına bakın).":"Orijinal Excel bu oturumda bulunamadı (sayfa yenilendi ya da dosya oturum belleğine sığmadı). Biçimsiz Excel üretildi; biçim için orijinali Adım 1'de yeniden yükleyin.",true,12000);save("EXCEL","biçimsiz yedek çıktı");exportedClean=true;
      }
    }catch(e){console.error(e);notify("Excel üretilemedi: "+e.message,true,15000);}
  }
  function printRoster(){const m=M();const r=m.result;if(!r)return;const w=document.createElement("div");w.id="printArea";const dates=C.monthDates(m.month);
    w.innerHTML=`<h1>${esc(C.monthLabel(m.month))} — Resmî (PROBEL) nöbet çizelgesi önerisi</h1><p>${esc(X.STATUS_TR[r.status]||r.status)} · ${new Date(r.generatedAt).toLocaleString("tr-TR")}</p><table><thead><tr><th>Tarih</th><th>Gün</th><th>SERVİS</th><th>ACİL ailesi</th></tr></thead><tbody>${dates.map(d=>{const a=r.assignments.filter(x=>x.date===d);return`<tr><td>${fd(d)}</td><td>${C.dayName(d)}</td><td>${a.filter(x=>x.category==="Servis").map(x=>esc(x.name)).join("<br>")}</td><td>${a.filter(x=>x.category==="Acil").map(x=>esc(x.name)).join("<br>")}</td></tr>`;}).join("")}</tbody></table>`;
    document.body.appendChild(w);window.print();setTimeout(()=>w.remove(),500);}

  /* ---------------- olaylar ---------------- */
  function bind(){
    $$(".step").forEach(b=>b.addEventListener("click",()=>showStep(b.dataset.step)));
    document.addEventListener("click",async e=>{
      const g=e.target.closest("[data-goto]");if(g){showStep(g.dataset.goto);return;}
      const t=e.target.closest("[data-tab]");if(t&&t.closest(".subtabs")){tab=t.dataset.tab;renderStep4();return;}
      if(!e.target.closest(".menu"))$("#dataMenu").hidden=true;
      const b=e.target.closest("[data-action]");if(!b||b.tagName==="SELECT")return;const a=b.dataset.action;const m=M();
      try{
      if(a==="pick-actual")$("#actualInput").click();
      else if(a==="confirm-import"){const errs=(m.actualSource?.issues||[]).filter(i=>i.level==="error");if(errs.length){const v=await dialog("İçe aktarmada hata var",`<p>Bu dosyada <b>${errs.length} hata</b> bulundu:</p><ul>${errs.slice(0,8).map(i=>`<li>${esc(i.message)}</li>`).join("")}</ul><p>Doğru dosya ve sayfa olduğundan eminseniz ve eksikleri bildiğiniz hâlde devam etmek istiyorsanız onaylayın. Bu karar işlem günlüğüne yazılır.</p><label class="check"><input type="checkbox" name="sure"> Hataları gördüm; sorumluluğu üstlenerek devam ediyorum</label><label>Adınız<input name="by"></label>`,{ok:"Hatalara rağmen onayla"});if(!v||!v.sure)return;m.actualSource.errorsAcknowledged={by:v.by||"kullanıcı",at:new Date().toISOString(),count:errs.length};save("FIILI_HATA_ONAY",`${errs.length} hata kabul edildi (${v.by||"kullanıcı"})`);}E.confirmActualImport(db,m.month,"kullanıcı");m.actual.forEach(r=>{if(r.confidence!=="yüksek")r.reviewed=true;});save("FIILI_ONAY","");render();notify("İçe aktarma onaylandı.");}
      else if(a==="unconfirm-import"){m.actualSource.confirmed=false;save("FIILI_ONAY_GERI","");render();}
      else if(a==="toggle-preview"){showPreview=!showPreview;renderStep1();}
      else if(a==="toggle-records"){showRecords=!showRecords;renderStep1();}
      else if(a==="download-version"){const rec=await ST.getFile(b.dataset.hash);if(rec)download(new Uint8Array(rec.bytes),rec.name);else notify("Bu sürümün dosyası bu tarayıcıda yok (metin yapıştırma veya başka bilgisayar).",true);}
      else if(a==="download-original"){const rec=await ST.getFile(m.actualSource.fileHash);if(rec)download(new Uint8Array(rec.bytes),rec.name);else notify("Orijinal dosya bu tarayıcıda yok.",true);}
      else if(a==="rec-ok"){const r=m.actual.find(x=>x.id===b.dataset.id);r.reviewed=true;r.confidence="onaylı";save("KAYIT_ONAY",`${r.rawName} ${r.date}`);render();}
      else if(a==="rec-ignore"){const r=m.actual.find(x=>x.id===b.dataset.id);const v=await dialog("Kaydı hakediş dışı bırak",`<p><b>${esc(r.rawName)}</b> · ${fd(r.date)} · ${esc(r.unit)}</p><p class="muted">Kaynak kayıt silinmez; hakedişe ve çizelgeye katılmaz, “Geri al” ile geri gelir.</p><label>Gerekçe<input name="why" required autofocus placeholder="ör. o gün nöbet tutulmadı (birim sorumlusu teyidi)"></label>`,{ok:"Hakediş dışı bırak"});if(!v)return;if(!v.why.trim())return notify("Gerekçe yazın.",true);r.status="ignored";r.ignoreReason=v.why.trim();r.ignoredAt=new Date().toISOString();if(m.result)m.result.stale=true;save("KAYIT_YOKSAY",`${r.rawName} ${r.date} ${r.unit} — ${r.ignoreReason}`);render();}
      else if(a==="rec-restore"){const r=m.actual.find(x=>x.id===b.dataset.id);r.status="active";if(m.result)m.result.stale=true;E.checkStale(db);save("KAYIT_GERI",`${r.rawName} ${r.date}`);render();}
      else if(a==="rec-edit"){const r=m.actual.find(x=>x.id===b.dataset.id);const v=await dialog("Fiilî kaydı düzelt",`<p class="muted">Kaynak hücre: ${esc(r.source?.sheet||"")}!${esc(r.source?.cell||"")} — “${esc(r.source?.cellText||"")}”</p><label>Personel adı<input name="name" value="${esc(r.rawName)}" required autofocus></label><label>Tarih<input type="date" name="date" value="${r.date}" min="${C.monthDates(m.month)[0]}" max="${C.monthDates(m.month).slice(-1)[0]}" required></label><label>Bölüm<select name="unit">${C.UNITS.map(u=>`<option ${u===r.unit?"selected":""}>${u}</option>`).join("")}</select></label><label>FMS (boş = kurala göre)<input type="number" step="0.5" name="fms" value="${r.fmsOverride??""}"></label><label>Düzeltme nedeni<input name="why" placeholder="ör. yazım hatası"></label>`);
        if(v){if(!v.name.trim())return notify("Ad boş olamaz.",true);/* tarih boş ya da ay dışı olamaz: kayıt sessizce hakedişten düşerdi (FABLE tur12b T12b-1) */if(!v.date||!v.date.startsWith(m.month))return notify(`Tarih seçili ay (${C.monthLabel(m.month)}) içinde olmalı; kayıt değiştirilmedi.`,true);if(!C.CATEGORY_OF_UNIT[v.unit])return notify("Bölüm seçin.",true);const old=`${r.rawName}/${r.date}/${r.unit}`;r.rawName=C.cleanSpaces(v.name);r.date=v.date;r.unit=v.unit;r.category=C.CATEGORY_OF_UNIT[v.unit];r.fmsOverride=v.fms===""?null:C.num(v.fms);r.reviewed=true;r.confidence="onaylı";r.flags=[...(r.flags||[]),"elle düzeltildi"];r.editReason=v.why||r.editReason||"";E.ensurePerson(db,r.rawName);/* düzeltilen kayıt hakedişi değiştirir: kayıtlı çizelge hemen “yeniden hesaplanmalı” */if(m.result)m.result.stale=true;E.checkStale(db);save("KAYIT_DUZELT",`${old} → ${r.rawName}/${r.date}/${r.unit}${v.why?" ("+v.why+")":""}`);render();}}
      else if(a==="add-actual"){const v=await dialog("Elle fiilî kayıt ekle",`<label>Personel adı<input name="name" required autofocus placeholder="Ad Soyad"></label><label>Tarih<input type="date" name="date" value="${C.monthDates(m.month)[0]}" required></label><label>Bölüm<select name="unit">${C.UNITS.map(u=>`<option>${u}</option>`).join("")}</select></label><label>Özel saat (isteğe bağlı)<input name="shift" placeholder="ör. 09.00-17.00"></label><label>FMS (boş = kurala göre)<input type="number" step="0.5" name="fms"></label><label>Kaynak / not<input name="note" placeholder="ör. sonradan eklenen görev"></label>`);
        if(v){const name=C.cleanSpaces(v.name);if(!name)return notify("Personel adı boş olamaz.",true);if(!v.date||!v.date.startsWith(m.month))return notify("Tarih seçili ay içinde olmalı.",true);const sh=v.shift?IA.parseShift(v.shift):null;E.ensurePerson(db,name);m.actual.push({id:C.uid("elle"),rawName:name,date:v.date,unit:v.unit,category:C.CATEGORY_OF_UNIT[v.unit],shift:sh,notes:v.note?[v.note]:[],orientation:false,flags:["elle"],confidence:"onaylı",manual:true,status:"active",fmsOverride:v.fms===""?null:C.num(v.fms),source:{file:"elle giriş",sheet:"",cell:"",cellText:v.note||""}});if(!m.actualSource)m.actualSource={fileName:"Elle giriş",confirmed:true,stats:{},issues:[],format:"elle"};m.result&&(m.result.stale=true);save("ELLE_FIILI",`${name} ${v.date} ${v.unit}`);showRecords=true;render();notify(`${name} için fiilî kayıt eklendi.`);}}
      else if(a==="legacy-prior-remove"||a==="legacy-current-remove"){if(a==="legacy-prior-remove"){const now=E.dropLegacyPrior(db,m.month,b.dataset.cat);notify(now?`Eski PROBEL listesi kaldırıldı; yerine ${C.monthLabel(C.prevMonth(m.month))} program çizelgesi geldi — “hepsi burada” onayını kontrol edin.`:"Eski PROBEL listesi kaldırıldı.",false,10000);}else E.dropLegacyCurrent(db,m.month);save("ESKI_PROBEL_KALDIR",a+" "+(b.dataset.cat||""));render();}
      else if(a==="prior-manual-del"){m.priorManual=m.priorManual.filter(x=>!(x.pid===b.dataset.pid&&x.date===b.dataset.date));save("AY_SONU_SIL","");E.checkStale(db);render();}
      else if(a==="prior-manual-add"){const name=C.cleanSpaces($("#pmName").value);if(!name)return notify("Personel adı girin.",true);const pid=E.ensurePerson(db,name);m.priorManual.push({pid,date:$("#pmDate").value,kind:"duty",at:new Date().toISOString()});save("AY_SONU_ELLE",`${name} ${$("#pmDate").value}`);E.checkStale(db);render();
        const staffNow=E.staffSummary(db,m);if(!staffNow.some(s=>s.pid===pid)){const sim=staffNow.filter(s=>{const x=C.nameSimilarity(E.personName(db,pid),s.name);return x&&x.kind!=="same"&&!E.isRejected(db,E.personName(db,pid),s.name);}).map(s=>s.name);notify(sim.length?`“${E.personName(db,pid)}” bu ayın listesinde birebir yok; benzer isim: ${sim.join(", ")}. Aynı kişi olup olmadığına Adım 2'de karar vermeniz istenecek; karar verilene kadar ay sınırı güvenli tarafta uygulanır.`:`“${E.personName(db,pid)}” bu ayın listesinde yok; adın listedeki yazımla aynı olduğundan emin olun.`,!!sim.length,12000);}}
      else if(a==="alias-same"||a==="alias-diff"){const s=E.aliasSuggestions(db,m.month)[+b.dataset.i];if(!s)return;if(a==="alias-diff"){E.rejectAlias(db,s.a,s.b,"kullanıcı");save("ISIM_FARKLI",`${s.a} ≠ ${s.b}`);}
        else{const cntA=m.actual.filter(r=>E.resolve(db,r.rawName)===s.pidA).length,cntB=m.actual.filter(r=>E.resolve(db,r.rawName)===s.pidB).length;const v=await dialog("Aynı kişi — hangi ad kullanılsın?",`<label class="check"><input type="radio" name="keep" value="a" ${cntA>=cntB?"checked":""}> ${esc(s.a)}</label><label class="check"><input type="radio" name="keep" value="b" ${cntB>cntA?"checked":""}> ${esc(s.b)}</label><p class="muted">Kimlik/sicil ile teyit ettiğinizden emin olun. Karar tüm aylarda geçerli olur.</p>`);if(!v)return;const ka=(v.keep||(cntA>=cntB?"a":"b"))==="a";
          if(ka)E.confirmAlias(db,s.b,s.a,"kullanıcı");else E.confirmAlias(db,s.a,s.b,"kullanıcı");save("ISIM_AYNI",`${s.a} = ${s.b}`);}
        if(m.result)m.result.stale=true;E.checkStale(db);render();}
      else if(a==="legacy-del"){const st=m.staff[b.dataset.pid];if(st){delete st[b.dataset.field];if(m.result)m.result.stale=true;save("IZIN_SIL",`${E.personName(db,b.dataset.pid)} ${b.dataset.field}`);renderStep2();renderDots();}}
      else if(a==="leave-add"){const pid=$("#lvPerson").value,kind=$("#lvKind").value,start=$("#lvStart").value,end=$("#lvEnd").value||$("#lvStart").value;if(!pid||!start)return notify("Personel ve başlangıç tarihi gerekli.",true);if(!E.okDate(start)||!E.okDate(end))return notify("Tarih geçersiz (ör. yıl beş haneli yazılmış). Tarihi gg.aa.yyyy olarak yeniden seçin.",true);if(end<start)return notify("Bitiş başlangıçtan önce olamaz.",true);const[t,k]=kind.split(":");if(t==="leave")m.leaves.push({id:C.uid("izin"),pid,start,end,kind:k,source:"kullanıcı",note:$("#lvNote").value});else m.unavailable.push({id:C.uid("uygun"),pid,start,end,mode:k,note:$("#lvNote").value});if(m.result)m.result.stale=true;save("IZIN_EKLE",`${E.personName(db,pid)} ${k} ${start}–${end}`);renderStep2();renderDots();}
      else if(a==="leave-del"){m.leaves=m.leaves.filter(x=>x.id!==b.dataset.id);if(m.result)m.result.stale=true;save("IZIN_SIL","");renderStep2();}
      else if(a==="un-del"){m.unavailable=m.unavailable.filter(x=>x.id!==b.dataset.id);if(m.result)m.result.stale=true;save("UYGUNLUK_SIL","");renderStep2();}
      else if(a==="dr-add"){const d=$("#drDate").value;if(!d||!d.startsWith(m.month))return notify("Bu ay içinde bir tarih seçin.",true);m.dailyRequirements=m.dailyRequirements.filter(x=>x.date!==d);m.dailyRequirements.push({date:d,serviceMin:C.num($("#drSmin").value),serviceMax:C.num($("#drSmax").value),emergencyMin:C.num($("#drEmin").value),emergencyMax:C.num($("#drEmax").value)});m.dailyRequirements.sort((x,y)=>x.date.localeCompare(y.date));rulesChanged("Gün istisnası");}
      else if(a==="dr-del"){m.dailyRequirements=m.dailyRequirements.filter(x=>x.date!==b.dataset.date);rulesChanged("Gün istisnası silindi");}
      else if(a==="hol-add"){const half=b.dataset.kind==="yarım gün";const d=$(half?"#halfDate":"#holDate").value;if(!d||!d.startsWith(m.month))return notify("Bu ay içinde bir tarih seçin.",true);E.addSpecialDay(db,m.month,{date:d,kind:half?"yarım gün":"tatil",label:$(half?"#halfLabel":"#holLabel").value});rulesChanged(half?"Yarım gün eklendi":"Tatil eklendi");}
      else if(a==="hol-del"){m.settings.holidays.splice(+b.dataset.i,1);rulesChanged("Tatil silindi");}
      else if(a==="shift-del"){/* kullanılan vardiyanın kuralı silinmez: o kayıtlar “veri eksik” kalır ve satır ancak Excel yeniden yüklenince geri gelirdi (tur12c) */const r=db.global.specialShiftRules[+b.dataset.i];if(!r)return;const used=Object.values(db.months).reduce((z,M)=>z+(M.actual||[]).filter(x=>x.status!=="ignored"&&x.shift&&x.shift.start===r.start&&x.shift.end===r.end).length,0);
        if(used){notify(`${r.start}–${r.end} vardiyası kayıtlı aylarda ${used} fiilî kayıtta kullanılıyor; kuralı silinemez. Değeri değiştirmek için kutudaki sayıyı düzeltin.`,true,10000);return;}
        const v=await dialog("Özel vardiya kuralını sil",`<p><b>${esc(r.start)}–${esc(r.end)}</b> vardiyasının FMS değerleri TÜM aylardan silinecek. Hiçbir fiilî kayıtta kullanılmıyor.</p>`,{ok:"Sil"});if(!v)return;db.global.specialShiftRules.splice(+b.dataset.i,1);rulesChanged(`Özel vardiya kuralı silindi: ${r.start}–${r.end}`);}
      else if(a==="run")run();
      else if(a==="sc-save"){const name=$("#scName").value.trim();if(!name)return notify("Senaryo adı girin.",true);m.scenarios=m.scenarios||[];m.scenarios.push({name,at:new Date().toISOString(),settings:C.clone(m.settings),dailyRequirements:C.clone(m.dailyRequirements),result:C.clone(m.result)});save("SENARYO_KAYDET",name);renderStep4();notify("Senaryo kaydedildi.");}
      else if(a==="sc-load"){const sc=(m.scenarios||[])[+b.dataset.i];if(!sc)return;m.settings=C.clone(sc.settings);m.dailyRequirements=C.clone(sc.dailyRequirements||[]);m.result=C.clone(sc.result);if(m.result)E.reaudit(db,m.month);save("SENARYO_YUKLE",sc.name);render();notify(`“${sc.name}” geri yüklendi ve güncel verilerle yeniden denetlendi.`);}
      else if(a==="export")await exportExcel();
      else if(a==="export-probel"){download(X.probelOnly(XLSX,db,m,m.result),`PROBEL_giris_${m.month}.xlsx`);save("PROBEL_LISTE","");}
      else if(a==="print")printRoster();
      else if(a==="carry"){const v=await dialog("Sonraki aya devret",`<p>${esc(C.monthLabel(m.month))} kapanışı ${esc(C.monthLabel(C.nextMonth(m.month)))} ayına aktarılacak:</p><ul><li>Bu ayın resmî son nöbetleri → sonraki ayın ilk günleri için engel (${m.currentOfficial.Servis||m.currentOfficial.Acil?"eski sürümden yüklenen PROBEL listesinden":"bu ayın önerisinden — sonraki ayda “hepsi burada” onayı istenir"})</li><li>Yetkili onaylı ve ödenmemiş farklar → açık alacak</li><li>Ödeme durumu bilinmeyen farklar → “mutabakat bekliyor” (alacak değil)</li><li>Ay sınırını aşan izinler, başlama/ayrılış ve klinik yetkiler</li></ul><p class="muted">Hariç tutulan kişiler sonraki aya taşınmaz.</p>`,{ok:"Devret"});if(!v)return;const N=E.carryToNext(db,m.month,"kullanıcı");db.activeMonth=N.month;save("DEVIR",N.month);showStep(1);notify(`${C.monthLabel(N.month)} açıldı; resmî ay sonu engelleri ve devirler aktarıldı. Şimdi bu ayın hastane Excel'ini yükleyin.`);}
      else if(a==="as-del"){E.manualEdit(db,m.month,{type:"remove",id:b.dataset.id});save("ELLE_RESMI_SIL","");renderStep4();renderDots();}
      else if(a==="as-add"){const staff=E.staffSummary(db,m).filter(s=>!s.excluded);const v=await dialog(`${fd(b.dataset.date)} ${b.dataset.cat} — elle ekle`,`<label>Personel<select name="pid">${staff.map(s=>`<option value="${esc(s.pid)}">${esc(s.name)}${s.history.length?` (${s.history.join("+")})`:""}</option>`).join("")}</select></label><p class="muted">Eklenen görev bağımsız denetimden geçer; kural ihlali varsa hata olarak gösterilir.</p>`);if(v){E.manualEdit(db,m.month,{type:"add",pid:v.pid,date:b.dataset.date,category:b.dataset.cat});save("ELLE_RESMI_EKLE",`${E.personName(db,v.pid)} ${b.dataset.date} ${b.dataset.cat}`);renderStep4();renderDots();}}
      else if(a==="ledger-add"){const kind=$("#lgKind").value,units=C.num($("#lgUnits").value),ref=$("#lgRef").value.trim();if(!(units>0))return notify("Eşdeğer saat girin.",true);
        if(kind==="payment"){const claimId=$("#lgClaim").value;if(!claimId)return notify("Ödemenin bağlı olduğu alacağı seçin.",true);const c=E.ledgerBalances(m).find(x=>x.claimId===claimId);E.addLedger(db,m.month,{kind:"payment",claimId,pid:c.pid,units,reference:ref});}
        else E.addLedger(db,m.month,{kind:"carry-open",pid:$("#lgPid").value,units,approvedBy:ref,sourceMonth:C.prevMonth(m.month),note:"elle açılış alacağı"});
        save("DEFTER",kind);renderStep4();notify("Defter kaydı eklendi.");}
      else if(a==="reload-page"){location.reload();}
      else if(a==="backup"){/* kullanıcının isteğiyle: çalışmanın tamamı (yüklenen dosyalar dahil) kullanıcının bilgisayarına */
        save("CALISMA_DOSYASI","");clearTimeout(saveTimer);flushSave();const obj=await ST.exportBackup(db);download(new Blob([JSON.stringify(obj)],{type:"application/json"}),`nobet_calisma_${db.activeMonth}_${new Date().toISOString().slice(0,10)}.json`);
        notify("Çalışma dosyası indirildi. Başka cihazda “Kaydedilmiş çalışmadan devam et” ile açabilirsiniz. Dosyada personel adları var; güvenli yerde saklayın.",false,12000);}
      else if(a==="restore"){$("#restoreInput").click();}
      else if(a==="finish"){const v=await dialog("Bitir ve temizle",`<p>Bu sekmedeki çalışmanın tamamı silinecek; tarayıcıda hiçbir şey kalmayacak.${exportedClean||!hasWork()?"":" <b class=\"bad-text\">Son değişikliklerden sonra Excel indirilmedi.</b>"}</p><p class="muted">Gelecek ay için gereken bilgi indirdiğiniz Excel'in “PROGRAM VERİSİ” sayfasındadır.</p><label class="check"><input type="checkbox" name="sure"> Excel'i indirdim ya da bu çalışmaya ihtiyacım yok</label>`,{ok:"Bitir ve temizle"});
        if(v&&v.sure){clearTimeout(saveTimer);dirty=false;ST.clearSession();db=E.newDb();db.activeMonth=todayMonth();E.ensureMonth(db,db.activeMonth);exportedClean=true;showRecords=false;showPreview=false;staffFilter="";{const sf=$("#staffFilter");if(sf)sf.value="";}showStep(1);notify("Oturum temizlendi; tarayıcıda bu çalışmadan hiçbir şey kalmadı.",false,8000);}}
      else if(a==="old-dismiss"){oldData=null;renderOldData();}
      else if(a==="rescue-download"){if(rescue)download(new Blob([rescue.raw],{type:"application/json"}),"okunamayan_oturum_"+new Date().toISOString().slice(0,10)+".json");}
      else if(a==="rescue-dismiss"){rescue=null;renderRescue();}
      else if(a==="quarantine-clear"){const mm=db.months[db.activeMonth];if(mm)delete mm.quarantine;save("KARANTINA_KAPAT","",{keepClean:true});renderQuarantine();}
      else if(a==="old-import"){if(hasWork()){const v=await dialog("Eski çalışmayı bu oturuma al",`<p>Bu sekmedeki çalışma eski kayıtla <b>değiştirilecek</b>.</p><label class="check"><input type="checkbox" name="sure"> Anladım</label>`,{ok:"Bu oturuma al"});if(!v||!v.sure)return;}
        const r=await ST.importOldData();let cand=null;try{cand=r.db||(r.v3&&r.v3.months?E.migrateV3(r.v3):null);}catch(e){cand=null;}if(!cand)return notify("Eski kayıt okunamadı. Bu sekmedeki çalışma değişmedi.",true,12000);
        try{adopt(cand);}catch(e){return notify("Eski kayıt oturuma alınamadı: "+e.message+". Bu sekmedeki çalışma değişmedi.",true,12000);}save("ESKI_SURUM_ALINDI",`${r.files} dosya`);notify("Eski çalışma bu oturuma alındı. Bilgisayardaki eski kaydı silmek için “Bu bilgisayardan sil”.",false,12000);}
      else if(a==="old-download"){const r=await ST.importOldData();const odb=r.db||(r.v3&&r.v3.months?E.migrateV3(r.v3):null);if(!odb)return notify("Eski kayıt okunamadı.",true);const obj=await ST.exportBackup(odb);download(new Blob([JSON.stringify(obj)],{type:"application/json"}),`eski_surum_kaydi_${new Date().toISOString().slice(0,10)}.json`);notify("Eski kayıt dosya olarak indirildi (personel adları içerir).",false,10000);}
      else if(a==="old-delete"){const v=await dialog("Eski kaydı bu bilgisayardan sil",`<p>Eski sürümün bu tarayıcıdaki kalıcı kaydı ve dosyaları <b>kalıcı olarak silinecek</b>. Bu sekmedeki çalışma etkilenmez.</p><label class="check"><input type="checkbox" name="sure"> Gerekirse önce “Dosya olarak indir” ile aldım; silinsin</label>`,{ok:"Sil"});if(!v||!v.sure)return;
        const res=await ST.deleteOldData();oldData=res.ok?null:res.left;renderOldData();notify(res.ok?"Eski kayıt bu bilgisayardan silindi.":"Eski kaydın bir kısmı silinemedi; tarayıcı ayarlarından site verisini temizleyin.",!res.ok,12000);}
      else if(a==="carry-file"){$("#carryInput").click();}
      else if(a==="help")await dialog("Kısa kullanım kılavuzu",HELP,{cancel:"",wide:true});
      else if(a==="talimat")await showTalimat();
      else if(a==="talimat-print"){const T=window.NobetTalimat;if(!T)return;const w=document.createElement("div");w.id="printArea";w.innerHTML=`<style>${T.CSS}</style>`+T.render(window.NobetTalimatVeri,{db,month:m.month,monthLabel:C.monthLabel(m.month)});document.body.appendChild(w);window.print();setTimeout(()=>w.remove(),500);}
      else if(a==="reset-month"){const v=await dialog("Bu ayı sıfırla",`<p><b>${esc(C.monthLabel(m.month))}</b> ayının tüm verileri (içe aktarma, ayarlar, çizelge, defter) silinecek. Önce yedek almanız önerilir. Diğer aylar etkilenmez.</p><label class="check"><input type="checkbox" name="sure"> Evet, bu ayı sıfırla</label>`,{ok:"Sıfırla"});if(v&&v.sure){delete db.months[m.month];E.ensureMonth(db,m.month);save("AY_SIFIRLANDI","");render();notify("Ay sıfırlandı.");}}
      }catch(err){console.error(err);notify(err.message,true,12000);}
    });
    document.addEventListener("change",async e=>{
      const x=e.target;const m=M();
      try{
      if(x.id==="actualInput"&&x.files[0]){await importActualFile(x.files[0]);x.value="";return;}
      if(x.id==="restoreInput"&&x.files[0]){try{const obj=JSON.parse(await x.files[0].text());
          const isV3=obj&&obj.version===3&&obj.months;const ver=obj&&obj.db?obj.db.version:null;
          if(!isV3&&!(obj&&obj.format==="pediatri-nobet-yedek"&&ver===E.DB_VERSION&&obj.db.months))throw new Error(obj&&obj.format==="pediatri-nobet-yedek"?`yedek farklı bir sürüme ait (sürüm ${ver}); bu uygulama v${E.DB_VERSION} bekliyor — geri yüklenmedi`:"bu dosya Pediatri Nöbet Dengeleyici yedeği değil");
          const months=Object.keys(isV3?obj.months:obj.db.months).sort();const curMonths=Object.keys(db.months).sort();
          const v=await dialog("Kaydedilmiş çalışmadan devam et",`<p>Bu sekmedeki çalışma dosyadakiyle <b>değiştirilecek</b>.</p><p>Şu anki aylar: ${esc(curMonths.map(C.monthLabel).join(", ")||"—")}<br>Dosyadaki aylar: ${esc(months.map(C.monthLabel).join(", ")||"—")}${isV3?"<br>(eski v3 dosyası — dönüştürülecek)":""}</p><label class="check"><input type="checkbox" name="sure"> Anladım, devam et</label>`,{ok:"Devam et"});
          if(!v||!v.sure){x.value="";return;}
          if(!isV3)E.validateDb(obj.db);const cand=isV3?E.migrateV3(obj):(await ST.importBackup(obj)).db;adopt(cand);save("CALISMA_DEVAM","");notify("Kaydedilmiş çalışma açıldı.",false,8000);}catch(err){notify("Dosya açılamadı: "+err.message+". Bu sekmedeki çalışma değişmedi.",true,12000);}x.value="";return;}
      if(x.id==="carryInput"&&x.files[0]){const f=x.files[0];x.value="";try{const bytes=await readBytes(f);const {payload,sha}=X.readCarry(XLSX,bytes);/* kopyada uygulanır: hata olursa oturum değişmez (FABLE T13-4) */const cand=JSON.parse(JSON.stringify(db));const res=E.applyCarryPayload(cand,m.month,payload,{name:f.name,sha});db=cand;save("ONCEKI_AY_CIKTISI",f.name);render();
          notify(`${C.monthLabel(res.prev)} çıktısından alındı: önerilen plan ${res.plan} nöbet${Object.keys(res.posted).length?", yüklenmiş PROBEL listeleri":""}, ${res.aliases} isim kararı, ${res.leaves} ay sonunu aşan izin, ${res.ledger} devir kaydı.${res.stale?" Dikkat: o ayın çizelgesi indirildiğinde yeniden hesaplanmamıştı.":""}${res.notes.length?" Not: "+res.notes.join("; "):""}`,!!res.stale,15000);}catch(err){const msg=/is not|undefined|null|Cannot|of null/.test(String(err&&err.message))?"dosyanın yapısı beklenmedik":err.message;notify("Geçen ayın çıktısı okunamadı: "+msg+(/oturum değişmedi/.test(msg)?"":" Oturum değişmedi."),true,15000);}return;}
      if(x.dataset.action==="change-sheet"){const rec=await ST.getFile(m.actualSource.fileHash);if(!rec)return notify("Orijinal dosya bu tarayıcıda yok; dosyayı yeniden seçin.",true);await applyActualBytes(new Uint8Array(rec.bytes),{name:rec.name,hash:m.actualSource.fileHash,size:rec.bytes.byteLength},x.value);return;}
      if(x.dataset.staff){const pid=x.dataset.pid,k=x.dataset.staff;const st=m.staff[pid]||(m.staff[pid]={});
        if(k==="exclude"){const i=m.exclusions.indexOf(pid);if(x.checked&&i<0)m.exclusions.push(pid);if(!x.checked&&i>=0)m.exclusions.splice(i,1);}
        else if(k==="earnedOverride"){if(x.value===""){delete st.earnedOverride;}else{const v=await dialog("Onaylı hakediş",`<p>${esc(E.personName(db,pid))} için satır hesabı yerine <b>${esc(x.value)}</b> Servis-eşdeğeri saat kullanılacak. Hesaplanan değerle fark varsa uyarı gösterilmeye devam eder.</p><label>Onay kaynağı / not<input name="note" required autofocus placeholder="ör. birim sorumlusu mutabakatı"></label>`);if(!v||!v.note.trim()){x.value=st.earnedOverride?.value??"";return notify("Onaylı değer için not/kaynak zorunlu.",true);}st.earnedOverride={value:C.num(x.value),note:v.note,by:"kullanıcı",at:new Date().toISOString()};}}
        else if(k==="authorizedCategory"){if(x.value){const v=await dialog("Kategori/klinik yetki",`<p>${esc(E.personName(db,pid))} bu ay fiilî kaynakta sayılan nöbeti olmadığı hâlde <b>${esc(x.value)}</b> kategorisine yazılabilecek. Bu bir klinik yetki kararıdır.</p><label>Yetkilendiren<input name="by" required autofocus></label>`);if(!v||!v.by.trim()){x.value=st.authorizedCategory||"";return;}st.authorizedCategory=x.value;st.authorizedBy=v.by;}else{delete st.authorizedCategory;delete st.authorizedBy;}}
        else if(x.type==="checkbox")st[k]=x.checked;else st[k]=x.value;
        if(m.result)m.result.stale=true;save("PERSONEL",`${E.personName(db,pid)} ${k}=${x.type==="checkbox"?x.checked:x.value}`);renderStep2();renderDots();renderStale();return;}
      if(x.dataset.set){const k=x.dataset.set;const s=m.settings;
        if(k==="priorListsComplete"){m.priorListsComplete=x.checked;save("ONCEKI_TAM",String(x.checked));E.checkStale(db);render();return;}
        if(k==="priorPlanConfirmed"){m.priorPlanConfirmed=x.checked;save("ONCEKI_PLAN_TEYIT",String(x.checked));E.checkStale(db);render();return;}
        if(k==="rulesConfirmed"){const pre=preflightNow().filter(i=>i.level==="error"&&/CAP_MISSING|MIN_MISSING|HOLIDAY_QUESTION|HALFDAY_QUESTION|DAYS_MISSING|ANSWER_CONFLICT/.test(i.code));if(x.checked&&pre.length){x.checked=false;return notify("Önce kadro sınırlarını girin: "+pre.map(i=>i.message).join(" "),true);}s.rulesConfirmed=x.checked;save("KURAL_ONAY",String(x.checked));render();return;}
        if(["emergencyCap","emergencyMin","serviceMin","serviceMax"].includes(k))s[k]=C.num(x.value);
        else if(k==="mode")s.mode=x.value;else if(x.type==="checkbox")s[k]=x.checked;else s[k]=x.value;
        rulesChanged(`${k}=${x.type==="checkbox"?x.checked:x.value}`,["approvedBy","safeBoundary"].includes(k));return;}
      if(x.id==="lvKind"){const md=C.monthDates(m.month);if(x.value==="leave:Henüz başlamadı"){$("#lvStart").value=md[0];if(!$("#lvEnd").value)$("#lvEnd").focus();}else if(x.value==="leave:İşten ayrıldı"){$("#lvEnd").value=md[md.length-1];if(!$("#lvStart").value)$("#lvStart").focus();}return;}
      if(x.dataset.special){E.setSpecialDayAnswer(db,m.month,x.dataset.special,x.value==="var");rulesChanged(`özel gün sorusu ${x.dataset.special}=${x.value}`);return;}
      if(x.dataset.hol){const h=m.settings.holidays[+x.dataset.i];if(x.dataset.hol==="fms")h.fms=C.num(x.value);else{if(x.checked&&C.num(h.fms)==null){x.checked=false;return notify("Önce FMS değerini girin.",true);}h.confirmed=x.checked;}rulesChanged(`tatil ${h.date}`);return;}
      if(x.dataset.shift){const r=db.global.specialShiftRules[+x.dataset.i];r.fms[x.dataset.shift]=C.num(x.value);r.note="kullanıcı girdi";rulesChanged(`vardiya ${r.start}-${r.end} ${x.dataset.shift}=${x.value}`);return;}
      if(x.id==="unlockFms"){$$("[data-fms],[data-factor]").forEach(i=>i.disabled=!x.checked);return;}
      if(x.dataset.fms!=null){const k=x.dataset.fms;db.global.fmsTable[k]=C.num(x.value);rulesChanged(`FMS ${FMS_RULE_LABEL[k]||C.DAYS_TR[+k]}=${x.value}`);return;}
      if(x.dataset.factor){db.global.factors[x.dataset.factor]=C.num(x.value);rulesChanged(`katsayı ${x.dataset.factor}=${x.value}`);return;}
      }catch(err){console.error(err);notify(err.message,true,12000);}
    });
    $("#staffFilter").addEventListener("input",e=>{staffFilter=e.target.value;renderStep2();});
    $("#openMonthBtn").onclick=()=>openMonth($("#monthPick").value);
    $("#dataMenuBtn").onclick=e=>{e.stopPropagation();$("#dataMenu").hidden=!$("#dataMenu").hidden;};
    /* sürükle-bırak */
    document.addEventListener("dragover",e=>{const z=e.target.closest("[data-drop]");if(z){e.preventDefault();z.classList.add("drag");}});
    document.addEventListener("dragleave",e=>{const z=e.target.closest("[data-drop]");if(z)z.classList.remove("drag");});
    document.addEventListener("drop",async e=>{const z=e.target.closest("[data-drop]");if(!z)return;e.preventDefault();z.classList.remove("drag");const f=e.dataTransfer.files[0];if(!f)return;if(z.dataset.drop==="actual")await importActualFile(f);});
    /* sayfa yenilenirken oturum belleğine yazılır; sekme kapanırken son değişiklikten sonra Excel indirilmediyse tarayıcı uyarır (kalıcı kayıt yok) */
    window.addEventListener("beforeunload",e=>{clearTimeout(saveTimer);if(dirty)flushSave();if(!exportedClean&&hasWork()){e.preventDefault();e.returnValue="";}});
    /* sekme arka plana geçince bekleyen kayıt hemen yazılır (arka planda zamanlayıcılar kısıtlanabilir) */
    document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden"&&dirty){clearTimeout(saveTimer);flushSave();}});
  }
  function rulesChanged(detail,keepConfirm=false){const m=M();if(!keepConfirm&&m.settings.rulesConfirmed){m.settings.rulesConfirmed=false;notify("Kural değişti; onay kaldırıldı. Kontrol edip yeniden onaylayın.");}if(m.result)m.result.stale=true;save("KURAL",detail);render();}

  const HELP=`<ol class="help">
    <li><b>Ayı seçin</b> (üstte). Geçen ayın program çıktısı Excel'ini yüklerseniz (Adım 1 → ②) geçen ayın son nöbetleri, isim kararları, vardiya FMS değerleri, ay sınırını aşan izinler ve açık devirler oradan gelir.</li>
    <li><b>Adım 1 — Dosyalar:</b> hastanenin aylık nöbet Excel'ini olduğu gibi bırakın. Program tarih satırlarını ve SERVİS/ACİL/YOĞUN BAKIM/YENİDOĞAN/KIDEMLİ sütunlarını bulur, alt alta yazılmış isimleri ayırır. Sarı işaretli hücreleri kontrol edip <b>İçe aktarmayı onayla</b>'ya basın. Sonra ② bölümünde geçen ayın son 3 günündeki resmî nöbetleri girin: geçen ayın <b>program çıktısı Excel'ini</b> yükleyin ya da kişileri <b>elle</b> ekleyin; ardından “hepsi burada” kutusunu işaretleyin. (PROBEL listesi yüklenmez.)</li>
    <li><b>Adım 2 — Kişiler:</b> benzer isim önerilerine karar verin; bu ay hariç tutulanları, izinleri, ödeme/devir durumunu girin.</li>
    <li><b>Adım 3 — Kurallar:</b> günlük Acil üst sınırı (ör. 8), Servis/Acil asgari kadro, tatil ve özel vardiya FMS değerlerini girip onaylayın.</li>
    <li><b>Adım 4 — Çizelge:</b> “Çizelgeyi oluştur”. Sonuç bağımsız denetimden geçer. <b>Excel indir</b> orijinal dosyanızın biçimini koruyarak resmî öneriyi ve tüm denetim sayfalarını üretir. <b>Excel indir</b> ile aldığınız dosyayı saklayın: gelecek ay Adım 1'de “Geçen ayın program çıktısı” olarak yüklenir.</li></ol>
    <p><b>Kesin kurallar:</b> kişi başı en çok 8 farklı resmî nöbet günü; nöbetler arası en az 2 tam boş gün (önceki ayın resmî son nöbetleri dahil); her kişi tek kategoride (fiilen yalnız Servis çalışan yalnız Servis'e, yalnız Acil ailesinde çalışan yalnız Acil'e); izin/hariç günlerine nöbet yok; çalışılmamış nöbet ücretli yazılmaz.</p>
    <p><b>Hakediş:</b> Servis-eşdeğeri saat = Servis FMS × 1 + Acil ailesi FMS × 1,5. Fark, ödeme teyidi ve yetkili onayı olmadan alacak sayılmaz.</p>
    <p><b>Veriler</b> kalıcı olarak saklanmaz: çalışma yalnız bu sekmede geçici tutulur (sayfa yenilenirse kalır, sekme kapanınca silinir). Yüklenen dosyalar hiçbir yere gönderilmez. İşiniz bitince Excel'i indirin ve <b>Veri ▾ → Bitir ve temizle</b>. Yarım kalan işi başka cihazda sürdürmek için Veri ▾ → “Çalışmayı dosyaya kaydet” / “Kaydedilmiş çalışmadan devam et”.</p>
    <p><b>İzin:</b> personelin çalışmadığı her gün (yıllık izin, rapor, doğum sonrası izni, mazeret, görevlendirme, işten ayrılış, henüz başlamamış olma) Adım 2'de izin olarak girilir; o günlerde resmî nöbet yazılmaz.</p>
    <p><b>Tüm parametreler ve kurallar:</b> Veri ▾ → “Talimatname” (paketteki TALIMATNAME.pdf ile aynı içerik + bu ayın güncel değerleri).</p>`;

  init();
})();
